      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[120] bg-white dark:bg-[#121212] pt-24 px-6 md:hidden animate-fade-in">
           <nav className="flex flex-col gap-6 text-center">
              <button onClick={() => { onNavigate('home'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Home</button>
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Produtos</button>
              <button onClick={() => { onNavigate('wishlist'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Favoritos</button>
              <button onClick={() => { onNavigate('cart'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Carrinho</button>
              <button onClick={() => { onNavigate('help'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Suporte</button>
           </nav>
        </div>
      )}
    </>
  );
};

export default Header;

import React, { useState, useRef, useEffect } from 'react';
import { MusicNoteIcon, MusicOffIcon } from './Icons';

const MusicPlayer: React.FC = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);
  const [isInfoVisible, setIsInfoVisible] = useState(false);
  const audioRef = useRef<HTMLAudioElement>(null);
  const clickTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const playlist = [
    { title: "West Coast Vibes", url: "https://cdn.pixabay.com/audio/2022/05/27/audio_1808fbf07a.mp3" },
    { title: "Chill Urban Trap", url: "https://cdn.pixabay.com/audio/2022/03/15/audio_c8c8a73467.mp3" },
    { title: "Energy Workout", url: "https://cdn.pixabay.com/audio/2022/03/23/audio_0579294e3d.mp3" },
    { title: "Midnight Rock", url: "https://cdn.pixabay.com/audio/2020/09/14/audio_a0a033282b.mp3" }
  ];

  const togglePlay = () => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.pause();
      } else {
        audioRef.current.play().catch(e => console.log("Play blocked"));
        showInfo();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleNextTrack = () => {
    setCurrentTrackIndex((prev) => (prev + 1) % playlist.length);
    setIsPlaying(true);
    showInfo();
  };

  const showInfo = () => {
    setIsInfoVisible(true);
    setTimeout(() => setIsInfoVisible(false), 4000);
  };

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (clickTimeoutRef.current) {
      // Duplo clique detectado
      clearTimeout(clickTimeoutRef.current);
      clickTimeoutRef.current = null;
      handleNextTrack();
    } else {
      // Aguardar para ver se é clique simples ou duplo
      clickTimeoutRef.current = setTimeout(() => {
        togglePlay();
        clickTimeoutRef.current = null;
      }, 300); // 300ms é o padrão para detecção de double click
    }
  };

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.src = playlist[currentTrackIndex].url;
      if (isPlaying) audioRef.current.play().catch(() => setIsPlaying(false));
    }
  }, [currentTrackIndex]);

  return (
    <div className="fixed bottom-24 left-6 z-[90] flex items-center">
      <audio ref={audioRef} onEnded={handleNextTrack} />

      {isInfoVisible && (
        <div className="absolute left-14 bg-black/80 text-white text-[10px] px-3 py-1.5 rounded-lg border border-brand-yellow/30 animate-fade-in whitespace-nowrap">
          <p className="font-bold text-brand-yellow">TOCANDO AGORA</p>
          <p>{playlist[currentTrackIndex].title}</p>
        </div>
      )}

      <button
        onClick={handleClick}
        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${isPlaying ? 'bg-brand-yellow text-black scale-110' : 'bg-gray-900 text-gray-400'}`}
      >
        {isPlaying ? <MusicNoteIcon className="w-6 h-6 animate-pulse" /> : <MusicOffIcon className="w-6 h-6" />}
      </button>
    </div>
  );
};

export default MusicPlayer;

import React, { useState, useMemo } from 'react';
import { Product, Filters } from '../data/products';
import { HeartIcon, HeartIconSolid, PlusIcon, MinusIcon, StarIcon } from './Icons';

interface ShopProps {
  products: Product[];
  onNavigate: (page: string, product: Product) => void;
  wishlistItems: Product[];
  onToggleWishlist: (product: Product) => void;
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

const normalizeText = (text: string) => {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
};

const StarRatingDisplay: React.FC<{ rating: number; reviewCount: number }> = ({ rating, reviewCount }) => (
    <div className="flex flex-col items-end justify-start gap-0.5">
        <div className="flex items-center justify-end">
            {[...Array(5)].map((_, i) => (
                <StarIcon key={i} className={`w-3 h-3 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-gray-300 dark:text-gray-600'}`} />
            ))}
        </div>
        <span className="text-[10px] text-gray-500 dark:text-gray-400 font-medium text-right leading-none whitespace-nowrap">
            ({reviewCount > 0 ? reviewCount : Math.floor(Math.random() * 20) + 1} avaliações)
        </span>
    </div>
);

export default function Shop({ products, onNavigate, wishlistItems, onToggleWishlist, filters, onFiltersChange }: ShopProps) {
  const [sortOrder, setSortOrder] = useState('featured');
  const [showFiltersMobile, setShowFiltersMobile] = useState(false);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
        const catMatch = filters.category === 'Todos' || p.category === filters.category;
        const brandMatch = filters.brand.length === 0 || filters.brand.includes(p.brand);
        const genderMatch = filters.gender.length === 0 || filters.gender.includes(p.gender);
        const styleMatch = filters.style.length === 0 || filters.style.includes(p.style);

        let queryMatch = true;
        if (filters.query) {
            const normalizedQuery = normalizeText(filters.query);
            queryMatch = normalizeText(p.name).includes(normalizedQuery) || 
                         normalizeText(p.brand).includes(normalizedQuery);
        }
        return catMatch && brandMatch && genderMatch && styleMatch && queryMatch;
    });
  }, [products, filters]);

  const sortedProducts = useMemo(() => {
    const list = [...filteredProducts];
    if (sortOrder === 'price-asc') return list.sort((a, b) => a.price - b.price);
    if (sortOrder === 'price-desc') return list.sort((a, b) => b.price - a.price);
    return list;
  }, [filteredProducts, sortOrder]);

  return (
    <div className="container mx-auto px-4 py-8 bg-white dark:bg-[#121212]">
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar Filters */}
        <aside className="w-full lg:w-1/4">
          <div className="sticky top-28 bg-gray-50 dark:bg-gray-900/50 p-6 rounded-2xl border border-gray-200 dark:border-gray-800">
            <h2 className="text-xl font-bold uppercase mb-6">Filtros</h2>
            {/* Aqui iriam os filtros simplificados para brevidade */}
            <button onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:''})} className="text-brand-yellow font-bold text-sm">LIMPAR FILTROS</button>
          </div>
        </aside>

        {/* Product Grid */}
        <main className="w-full lg:w-3/4">
          <div className="flex justify-between items-center mb-8 bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl">
             <p className="text-sm font-bold">{sortedProducts.length} Produtos</p>
             <select value={sortOrder} onChange={(e) => setSortOrder(e.target.value)} className="bg-transparent font-bold text-sm focus:outline-none">
                <option value="featured">Destaques</option>
                <option value="price-asc">Menor Preço</option>
                <option value="price-desc">Maior Preço</option>
             </select>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {sortedProducts.map(product => {
                const isWish = wishlistItems.some(i => i.id === product.id);
                return (
                    <div key={product.id} className="group bg-white dark:bg-[#181818] rounded-2xl border border-gray-200 dark:border-gray-800 overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all" onClick={() => onNavigate('productDetail', product)}>
                        <div className="relative aspect-[4/5] overflow-hidden">
                            <img src={product.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="" />
                            <button onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }} className="absolute top-4 right-4 p-2 bg-white/80 dark:bg-black/80 rounded-full backdrop-blur">
                                {isWish ? <HeartIconSolid className="w-5 h-5 text-red-500" /> : <HeartIcon className="w-5 h-5" />}
                            </button>
                        </div>
                        <div className="p-4">
                            <div className="flex justify-between items-start mb-1">
                                <h3 className="font-bold text-sm uppercase truncate">{product.name}</h3>
                                <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                            </div>
                            <p className="text-xs text-gray-500 mb-4">{product.brand}</p>
                            <p className="font-black text-lg">R$ {product.price.toFixed(2)}</p>
                        </div>
                    </div>
                );
            })}
          </div>
        </main>
      </div>
    </div>
  );
}

