import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductShowcase from './components/ProductShowcase';
import FeaturedCategories from './components/FeaturedCategories';
import VideoAction from './components/VideoAction';
import Spotlight from './components/Spotlight';
import FeaturedProducts from './components/FeaturedProducts';
import Footer from './components/Footer';
import Cart from './components/Cart';
import ProductDetail from './components/ProductDetail';
import Shop from './components/Shop';
import Checkout from './components/Checkout';
import OrderConfirmation from './components/OrderConfirmation';
import Wishlist from './components/Wishlist';
import Help from './components/Help';
import Login from './components/Login';
import LeadCapture from './components/LeadCapture';
import VideoModal from './components/VideoModal';
import MusicPlayer from './components/MusicPlayer';
import { Product, CartItem, Order, Filters, products } from './data/products';
import { CheckCircleIcon, HeartIconSolid, ExclamationCircleIcon, WhatsAppIcon } from './components/Icons';

const Toast = ({ message, icon }: { message: string, icon: 'success' | 'heart' | 'error' }) => (
  <div className="fixed bottom-32 md:bottom-20 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-3 bg-black dark:bg-white text-white dark:text-black py-3 px-6 rounded-full shadow-2xl animate-fade-in border border-brand-yellow/30">
    {icon === 'success' && <CheckCircleIcon className="w-6 h-6 text-brand-yellow" />}
    {icon === 'heart' && <HeartIconSolid className="w-6 h-6 text-red-500" />}
    {icon === 'error' && <ExclamationCircleIcon className="w-6 h-6 text-red-500" />}
    <span className="font-semibold">{message}</span>
  </div>
);

export default function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [wishlistItems, setWishlistItems] = useState<Product[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [completedOrder, setCompletedOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string; icon: 'success' | 'heart' | 'error' } | null>(null);
  const [isVideoModalOpen, setIsVideoModalOpen] = useState(false);
  const [currentVideoUrl, setCurrentVideoUrl] = useState('');
  const [activeFilters, setActiveFilters] = useState<Filters>({
    category: 'Todos',
    brand: [],
    gender: [],
    style: [],
    query: '',
  });

  useEffect(() => {
    document.documentElement.classList.remove('light', 'dark');
    document.documentElement.classList.add(theme);
  }, [theme]);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const navigateTo = (page: string, product?: Product, filters?: Partial<Filters>) => {
    if (filters) setActiveFilters(prev => ({ ...prev, ...filters }));
    if (page === 'productDetail' && product) setSelectedProduct(product);
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddToCart = (product: Product, quantity: number, size: string, color: string) => {
    const cartItemId = `${product.id}-${size}-${color}`;
    setCartItems(prev => {
      const existing = prev.find(item => item.cartItemId === cartItemId);
      if (existing) {
        return prev.map(item => item.cartItemId === cartItemId ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity, selectedSize: size, selectedColor: color, cartItemId }];
    });
    setToast({ message: `${product.name} adicionado ao carrinho!`, icon: 'success' });
  };

  const handleToggleWishlist = (product: Product) => {
    setWishlistItems(prev => {
      const exists = prev.some(item => item.id === product.id);
      if (exists) {
        setToast({ message: 'Removido dos favoritos', icon: 'heart' });
        return prev.filter(item => item.id !== product.id);
      }
      setToast({ message: 'Adicionado aos favoritos!', icon: 'heart' });
      return [...prev, product];
    });
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'shop': return <Shop products={products} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} filters={activeFilters} onFiltersChange={setActiveFilters} />;
      case 'cart': return <Cart cartItems={cartItems} onContinueShopping={() => navigateTo('shop')} onQuantityChange={(id, d) => setCartItems(prev => prev.map(item => item.cartItemId === id ? { ...item, quantity: Math.max(1, item.quantity + d) } : item))} onRemoveItem={id => setCartItems(prev => prev.filter(item => item.cartItemId !== id))} onCheckout={() => navigateTo('checkout')} />;
      case 'productDetail': return selectedProduct ? <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} allProducts={products} onNavigate={navigateTo} /> : null;
      case 'checkout': return <Checkout cartItems={cartItems} onPlaceOrder={(details) => { setCompletedOrder({ id: `RI-${Date.now()}`, items: cartItems, total: cartItems.reduce((a, b) => a + b.price * b.quantity, 0), customer: details }); setCartItems([]); navigateTo('orderConfirmation'); }} />;
      case 'orderConfirmation': return completedOrder ? <OrderConfirmation order={completedOrder} onContinueShopping={() => navigateTo('shop')} /> : null;
      case 'wishlist': return <Wishlist wishlistItems={wishlistItems} onNavigate={navigateTo} onToggleWishlist={handleToggleWishlist} onAddToCart={handleAddToCart} />;
      case 'help': return <Help />;
      case 'login': return <Login />;
      case 'leadCapture': return <LeadCapture onNavigate={() => navigateTo('home')} />;
      default: return (
        <>
          <Hero onNavigate={navigateTo} />
          <ProductShowcase products={products} onNavigate={navigateTo} />
          <FeaturedCategories onNavigate={navigateTo} />
          <VideoAction onOpenVideo={(url) => { setCurrentVideoUrl(url); setIsVideoModalOpen(true); }} />
          <Spotlight onNavigate={navigateTo} />
          <FeaturedProducts products={products.slice(0, 3)} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} />
        </>
      );
    }
  };

  return (
    <div className="min-h-screen bg-white dark:bg-[#121212] text-gray-900 dark:text-white transition-colors duration-300 font-sans">
      <Header 
        products={products} 
        currentPage={currentPage} 
        onNavigate={navigateTo} 
        theme={theme} 
        onToggleTheme={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} 
        cartCount={cartItems.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlistItems.length} 
      />

      <main className="pb-10 min-h-[calc(100vh-160px)]">{renderContent()}</main>

      <Footer onNavigate={navigateTo} />

      {toast && <Toast message={toast.message} icon={toast.icon} />}
      {isVideoModalOpen && <VideoModal videoUrl={currentVideoUrl} onClose={() => setIsVideoModalOpen(false)} />}

      <MusicPlayer />

      {/* WhatsApp FAB - Fixed Position */}
      <a 
        href="https://wa.me/5521985516518" 
        target="_blank" 
        className="fixed bottom-6 right-6 z-[95] bg-[#25D366] p-4 rounded-full shadow-[0_10px_25px_rgba(0,0,0,0.3)] hover:scale-110 transition-transform flex items-center justify-center"
      >
        <WhatsAppIcon className="w-8 h-8 text-white" />
      </a>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { LogoIcon, SearchIcon, MoonIcon, SunIcon, HeartIcon, BagIcon, ArrowLeftIcon, MenuIcon, CloseIcon } from './Icons';
import { Product, Filters } from '../data/products';

interface HeaderProps {
  products: Product[];
  currentPage: string;
  onNavigate: (page: string, product?: any, filters?: Partial<Filters>) => void;
  theme: 'light' | 'dark';
  onToggleTheme: () => void;
  cartCount: number;
  wishlistCount: number;
}

const Header: React.FC<HeaderProps> = ({ products, currentPage, onNavigate, theme, onToggleTheme, cartCount, wishlistCount }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState<Product[]>([]);
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  const normalizeText = (text: string) => {
    return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  };

  useEffect(() => {
    if (searchTerm.trim() === '') {
      setSearchResults([]);
      return;
    }
    const lowerCaseTerm = normalizeText(searchTerm);
    const results = products.filter(p =>
      normalizeText(p.name).includes(lowerCaseTerm) ||
      normalizeText(p.brand).includes(lowerCaseTerm) ||
      normalizeText(p.category).includes(lowerCaseTerm)
    ).slice(0, 5);
    setSearchResults(results);
  }, [searchTerm, products]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleResultClick = (product: Product) => {
    setSearchTerm('');
    setSearchResults([]);
    onNavigate('productDetail', product);
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      onNavigate('shop', undefined, { query: searchTerm });
      setSearchTerm('');
      setIsSearchFocused(false);
    }
  };

  return (
    <>
      <header className="bg-white dark:bg-[#121212]/95 backdrop-blur-md sticky top-0 z-[100] w-full border-b border-gray-200 dark:border-gray-800 transition-colors duration-300 h-16 md:h-24">
        <div className="container mx-auto px-4 h-full">
          <div className="flex items-center justify-between h-full gap-4">

            {/* Logo Section - Left Aligned */}
            <div className="flex items-center gap-2 md:gap-4 flex-shrink-0 z-20">
              {currentPage !== 'home' && (
                <button onClick={() => onNavigate('home')} className="hidden md:block p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                    <ArrowLeftIcon className="w-6 h-6 text-gray-900 dark:text-white" />
                </button>
              )}
              <button onClick={() => onNavigate('home')} className="hover:scale-105 transition-transform duration-200 block flex-shrink-0">
                <LogoIcon className="h-6 md:h-8 lg:h-9 w-auto" />
              </button>
            </div>

            {/* Search Bar - Center Aligned */}
            <form onSubmit={handleSearchSubmit} className="hidden md:flex flex-1 max-w-xl relative min-w-0 z-10" onBlur={() => setTimeout(() => setIsSearchFocused(false), 200)}>
              <div className="relative group w-full">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                  <SearchIcon className="h-5 w-5 text-gray-400 group-focus-within:text-brand-yellow transition-colors" />
                </div>
                <input
                  type="text"
                  placeholder="Buscar na loja..."
                  className="bg-gray-100 dark:bg-gray-800 text-black dark:text-white placeholder-gray-500 w-full pl-12 pr-4 py-3 rounded-full border border-transparent focus:outline-none focus:ring-2 focus:ring-brand-yellow shadow-sm"
                  value={searchTerm}
                  onChange={handleSearchChange}
                  onFocus={() => setIsSearchFocused(true)}
                />
              </div>
              {isSearchFocused && searchResults.length > 0 && (
                <div className="absolute top-full mt-2 w-full bg-white dark:bg-gray-900 rounded-xl shadow-2xl overflow-hidden border border-gray-200 dark:border-gray-700 animate-fade-in z-[110]">
                  <ul>
                    {searchResults.map(product => (
                      <li key={product.id}>
                        <button onClick={() => handleResultClick(product)} className="w-full flex items-center gap-4 p-3 text-left hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors border-b dark:border-gray-800 last:border-0">
                          <img src={product.image} className="w-12 h-12 object-cover rounded" alt="" />
                          <div className="flex-1 truncate">
                            <p className="font-bold text-sm text-black dark:text-white truncate">{product.name}</p>
                            <p className="text-xs text-gray-500">{product.brand}</p>
                          </div>
                          <span className="text-sm font-bold text-brand-yellow">R$ {product.price.toFixed(2)}</span>
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </form>

            {/* Navigation Icons - Right Aligned */}
            <div className="flex items-center gap-3 md:gap-6 flex-shrink-0 z-20">
              <nav className="hidden lg:flex items-center gap-6 mr-4">
                <button onClick={() => onNavigate('shop')} className="text-sm font-bold uppercase tracking-widest hover:text-brand-yellow transition-colors">Loja</button>
                <button onClick={() => onNavigate('help')} className="text-sm font-bold uppercase tracking-widest hover:text-brand-yellow transition-colors">Ajuda</button>
              </nav>

              <button onClick={onToggleTheme} className="text-gray-900 dark:text-white hover:text-brand-yellow transition-colors">
                {theme === 'dark' ? <SunIcon className="w-6 h-6" /> : <MoonIcon className="w-6 h-6" />}
              </button>
              <button onClick={() => onNavigate('wishlist')} className="relative text-gray-900 dark:text-white hover:text-brand-yellow transition-colors">
                <HeartIcon className="w-6 h-6" />
                {wishlistCount > 0 && <span className="absolute -top-2 -right-2 bg-brand-yellow text-black text-[10px] font-bold h-4 w-4 rounded-full flex items-center justify-center">{wishlistCount}</span>}
              </button>
              <button onClick={() => onNavigate('cart')} className="relative text-gray-900 dark:text-white hover:text-brand-yellow transition-colors">
                <BagIcon className="w-6 h-6" />
                {cartCount > 0 && <span className="absolute -top-2 -right-2 bg-brand-yellow text-black text-[10px] font-bold h-4 w-4 rounded-full flex items-center justify-center">{cartCount}</span>}
              </button>
              <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="md:hidden text-gray-900 dark:text-white">
                {isMobileMenuOpen ? <CloseIcon className="w-7 h-7" /> : <MenuIcon className="w-7 h-7" />}
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[120] bg-white dark:bg-[#121212] pt-24 px-6 md:hidden animate-fade-in">
           <nav className="flex flex-col gap-6 text-center">
              <button onClick={() => { onNavigate('home'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Home</button>
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Produtos</button>
              <button onClick={() => { onNavigate('wishlist'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Favoritos</button>
              <button onClick={() => { onNavigate('cart'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Carrinho</button>
              <button onClick={() => { onNavigate('help'); setIsMobileMenuOpen(false); }} className="text-2xl font-display uppercase">Suporte</button>
           </nav>
        </div>
      )}
    </>
  );
};

