import React, { useState, useEffect } from 'react';
import { LogoIcon, SearchIcon, HeartIcon, BagIcon, MenuIcon, CloseIcon } from './Icons';
import { Product, Filters } from '../data/products';

interface HeaderProps {
  products: Product[];
  currentPage: string;
  onNavigate: (page: string, product?: any, filters?: Partial<Filters>) => void;
  theme: 'light' | 'dark';
  onToggleTheme: () => void;
  cartCount: number;
  wishlistCount: number;
}

const Header: React.FC<HeaderProps> = ({ products, currentPage, onNavigate, cartCount, wishlistCount }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      onNavigate('shop', undefined, { query: searchTerm });
      setSearchTerm('');
      setIsSearchFocused(false);
    }
  };

  return (
    <>
      <header className="bg-white border-b border-[#e5e5e5] sticky top-0 z-[100] w-full transition-all duration-300">
        <div className="container mx-auto px-4 lg:px-12 h-16 md:h-20 flex items-center justify-between gap-8">

          <div className="flex-shrink-0">
            <button onClick={() => onNavigate('home')} className="hover:opacity-70 transition-opacity">
              <LogoIcon className="h-6 md:h-8 w-auto text-[#111111]" />
            </button>
          </div>

          <nav className="hidden lg:flex items-center gap-8">
            <button onClick={() => onNavigate('shop')} className="text-sm font-bold hover:text-[#757575] uppercase tracking-tighter">Lançamentos</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Masculino'] })} className="text-sm font-bold hover:text-[#757575] uppercase tracking-tighter">Masculino</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Feminino'] })} className="text-sm font-bold hover:text-[#757575] uppercase tracking-tighter">Feminino</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Kids'] })} className="text-sm font-bold hover:text-[#757575] uppercase tracking-tighter">Kids</button>
            <button onClick={() => onNavigate('shop')} className="text-sm font-bold hover:text-[#757575] uppercase tracking-tighter">Ofertas</button>
          </nav>

          <div className="flex-1 max-w-sm relative hidden md:block">
            <form onSubmit={handleSearchSubmit} className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <SearchIcon className="h-5 w-5 text-[#111111]" />
              </div>
              <input
                type="text"
                placeholder="Buscar"
                className="bg-[#f5f5f5] hover:bg-[#ebebeb] text-[#111111] w-full pl-10 pr-4 py-2 rounded-full border-none focus:ring-0 transition-colors"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onFocus={() => setIsSearchFocused(true)}
                onBlur={() => setTimeout(() => setIsSearchFocused(false), 200)}
              />
            </form>
          </div>

          <div className="flex items-center gap-4 md:gap-6">
            <button onClick={() => onNavigate('wishlist')} className="relative p-2 hover:bg-[#f5f5f5] rounded-full transition-colors">
              <HeartIcon className="w-6 h-6 text-[#111111]" />
              {wishlistCount > 0 && <span className="absolute top-1 right-1 bg-[#111111] text-white text-[9px] font-bold h-4 w-4 rounded-full flex items-center justify-center">{wishlistCount}</span>}
            </button>
            <button onClick={() => onNavigate('cart')} className="relative p-2 hover:bg-[#f5f5f5] rounded-full transition-colors">
              <BagIcon className="w-6 h-6 text-[#111111]" />
              {cartCount > 0 && <span className="absolute top-1 right-1 bg-[#111111] text-white text-[9px] font-bold h-4 w-4 rounded-full flex items-center justify-center">{cartCount}</span>}
            </button>
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2">
              {isMobileMenuOpen ? <CloseIcon className="w-6 h-6" /> : <MenuIcon className="w-6 h-6" />}
            </button>
          </div>
        </div>
      </header>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[120] bg-white pt-20 px-8 lg:hidden animate-fade-in">
           <nav className="flex flex-col gap-8 text-left">
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-2xl font-black uppercase italic">Lançamentos</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Masculino'] }); setIsMobileMenuOpen(false); }} className="text-2xl font-black uppercase italic">Masculino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Feminino'] }); setIsMobileMenuOpen(false); }} className="text-2xl font-black uppercase italic">Feminino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Kids'] }); setIsMobileMenuOpen(false); }} className="text-2xl font-black uppercase italic">Kids</button>
              <button onClick={() => { onNavigate('wishlist'); setIsMobileMenuOpen(false); }} className="text-xl font-bold uppercase border-t pt-8">Favoritos</button>
              <button onClick={() => { onNavigate('help'); setIsMobileMenuOpen(false); }} className="text-xl font-bold uppercase">Ajuda</button>
           </nav>
        </div>
      )}
    </>
  );
};

