import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductShowcase from './components/ProductShowcase';
import FeaturedCategories from './components/FeaturedCategories';
import VideoAction from './components/VideoAction';
import Spotlight from './components/Spotlight';
import FeaturedProducts from './components/FeaturedProducts';
import Footer from './components/Footer';
import Cart from './components/Cart';
import ProductDetail from './components/ProductDetail';
import Shop from './components/Shop';
import Checkout from './components/Checkout';
import OrderConfirmation from './components/OrderConfirmation';
import Wishlist from './components/Wishlist';
import Help from './components/Help';
import Login from './components/Login';
import LeadCapture from './components/LeadCapture';
import VideoModal from './components/VideoModal';
import QuickViewModal from './components/QuickViewModal';
import { Product, CartItem, Order, Filters, products } from './data/products';
import { CheckCircleIcon, HeartIconSolid, ExclamationCircleIcon, WhatsAppIcon } from './components/Icons';

const Toast = ({ message, icon }: { message: string, icon: 'success' | 'heart' | 'error' }) => (
  <div className="fixed bottom-32 md:bottom-20 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-3 bg-black dark:bg-white text-white dark:text-black py-3 px-6 rounded-full shadow-2xl animate-fade-in border border-brand-yellow/30">
    {icon === 'success' && <CheckCircleIcon className="w-6 h-6 text-brand-yellow" />}
    {icon === 'heart' && <HeartIconSolid className="w-6 h-6 text-red-500" />}
    {icon === 'error' && <ExclamationCircleIcon className="w-6 h-6 text-red-500" />}
    <span className="font-semibold text-sm uppercase tracking-wider">{message}</span>
  </div>
);

export default function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [quickViewProduct, setQuickViewProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [wishlistItems, setWishlistItems] = useState<Product[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [completedOrder, setCompletedOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string; icon: 'success' | 'heart' | 'error' } | null>(null);
  const [isVideoModalOpen, setIsVideoModalOpen] = useState(false);
  const [currentVideoUrl, setCurrentVideoUrl] = useState('');
  const [activeFilters, setActiveFilters] = useState<Filters>({
    category: 'Todos',
    brand: [],
    gender: [],
    style: [],
    query: '',
  });

  useEffect(() => {
    document.documentElement.classList.remove('light', 'dark');
    document.documentElement.classList.add(theme);
  }, [theme]);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const navigateTo = (page: string, product?: Product, filters?: Partial<Filters>) => {
    if (filters) setActiveFilters(prev => ({ ...prev, ...filters }));
    if (page === 'productDetail' && product) setSelectedProduct(product);
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddToCart = (product: Product, quantity: number, size: string, color: string) => {
    const cartItemId = `${product.id}-${size}-${color}`;
    setCartItems(prev => {
      const existing = prev.find(item => item.cartItemId === cartItemId);
      if (existing) {
        return prev.map(item => item.cartItemId === cartItemId ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity, selectedSize: size, selectedColor: color, cartItemId }];
    });
    setToast({ message: `${product.name} no carrinho!`, icon: 'success' });
  };

  const handleToggleWishlist = (product: Product) => {
    setWishlistItems(prev => {
      const exists = prev.some(item => item.id === product.id);
      if (exists) {
        setToast({ message: 'Removido dos favoritos', icon: 'heart' });
        return prev.filter(item => item.id !== product.id);
      }
      setToast({ message: 'Adicionado aos favoritos!', icon: 'heart' });
      return [...prev, product];
    });
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'shop': return <Shop products={products} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} filters={activeFilters} onFiltersChange={setActiveFilters} />;
      case 'cart': return <Cart cartItems={cartItems} onContinueShopping={() => navigateTo('shop')} onQuantityChange={(id, d) => setCartItems(prev => prev.map(item => item.cartItemId === id ? { ...item, quantity: Math.max(1, item.quantity + d) } : item))} onRemoveItem={id => setCartItems(prev => prev.filter(item => item.cartItemId !== id))} onCheckout={() => navigateTo('checkout')} />;
      case 'productDetail': return selectedProduct ? <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} allProducts={products} onNavigate={navigateTo} /> : null;
      case 'checkout': return <Checkout cartItems={cartItems} onPlaceOrder={(details) => { setCompletedOrder({ id: `RI-${Date.now()}`, items: cartItems, total: cartItems.reduce((a, b) => a + b.price * b.quantity, 0), customer: details }); setCartItems([]); navigateTo('orderConfirmation'); }} />;
      case 'orderConfirmation': return completedOrder ? <OrderConfirmation order={completedOrder} onContinueShopping={() => navigateTo('shop')} /> : null;
      case 'wishlist': return <Wishlist wishlistItems={wishlistItems} onNavigate={navigateTo} onToggleWishlist={handleToggleWishlist} onAddToCart={handleAddToCart} />;
      case 'help': return <Help />;
      case 'login': return <Login />;
      case 'leadCapture': return <LeadCapture onNavigate={() => navigateTo('home')} />;
      default: return (
        <>
          <Hero onNavigate={navigateTo} />
          <ProductShowcase products={products} onNavigate={navigateTo} />
          <FeaturedCategories onNavigate={navigateTo} />
          <VideoAction onOpenVideo={(url) => { setCurrentVideoUrl(url); setIsVideoModalOpen(true); }} />
          <Spotlight onNavigate={navigateTo} />
          <FeaturedProducts products={products.slice(0, 3)} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} />
        </>
      );
    }
  };

  return (
    <div className="min-h-screen bg-white dark:bg-[#121212] text-gray-900 dark:text-white transition-colors duration-300 font-sans">
      <Header 
        products={products} 
        currentPage={currentPage} 
        onNavigate={navigateTo} 
        theme={theme} 
        onToggleTheme={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} 
        cartCount={cartItems.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlistItems.length} 
      />

      <main className="pb-10 min-h-[calc(100vh-160px)]">{renderContent()}</main>

      <Footer onNavigate={navigateTo} />

      {toast && <Toast message={toast.message} icon={toast.icon} />}

      {isVideoModalOpen && <VideoModal videoUrl={currentVideoUrl} onClose={() => setIsVideoModalOpen(false)} />}

      {quickViewProduct && (
        <QuickViewModal 
          product={quickViewProduct} 
          onClose={() => setQuickViewProduct(null)} 
          onAddToCart={handleAddToCart} 
          onNavigateToProduct={(p) => { setQuickViewProduct(null); navigateTo('productDetail', p); }} 
        />
      )}

      <a 
        href="https://wa.me/5521985516518" 
        target="_blank" 
        className="fixed bottom-6 right-6 z-[95] bg-[#25D366] p-4 rounded-full shadow-[0_10px_25px_rgba(0,0,0,0.3)] hover:scale-110 transition-transform flex items-center justify-center border-2 border-white/20"
      >
        <WhatsAppIcon className="w-8 h-8 text-white" />
      </a>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Product, Filters } from '../data/products';
import { HeartIcon, HeartIconSolid, StarIcon } from './Icons';

interface ShopProps {
  products: Product[];
  onNavigate: (page: string, product: Product) => void;
  wishlistItems: Product[];
  onToggleWishlist: (product: Product) => void;
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

const normalizeText = (text: string) => {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
};

const StarRatingDisplay: React.FC<{ rating: number; reviewCount: number }> = ({ rating, reviewCount }) => (
    <div className="flex flex-col items-end justify-start gap-0.5">
        <div className="flex items-center justify-end">
            {[...Array(5)].map((_, i) => (
                <StarIcon key={i} className={`w-3 h-3 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-gray-300 dark:text-gray-600'}`} />
            ))}
        </div>
        <span className="text-[10px] text-gray-500 dark:text-gray-400 font-medium text-right leading-none whitespace-nowrap">
            ({reviewCount > 0 ? reviewCount : Math.floor(Math.random() * 20) + 1} avaliações)
        </span>
    </div>
);

export default function Shop({ products, onNavigate, wishlistItems, onToggleWishlist, filters, onFiltersChange }: ShopProps) {
  const [sortOrder, setSortOrder] = useState('featured');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
        const catMatch = filters.category === 'Todos' || p.category === filters.category;
        const brandMatch = filters.brand.length === 0 || filters.brand.includes(p.brand);
        const genderMatch = filters.gender.length === 0 || filters.gender.includes(p.gender);
        const styleMatch = filters.style.length === 0 || filters.style.includes(p.style);

        let queryMatch = true;
        if (filters.query) {
            const normalizedQuery = normalizeText(filters.query);
            queryMatch = normalizeText(p.name).includes(normalizedQuery) || 
                         normalizeText(p.brand).includes(normalizedQuery);
        }
        return catMatch && brandMatch && genderMatch && styleMatch && queryMatch;
    });
  }, [products, filters]);

  const sortedProducts = useMemo(() => {
    const list = [...filteredProducts];
    if (sortOrder === 'price-asc') return list.sort((a, b) => a.price - b.price);
    if (sortOrder === 'price-desc') return list.sort((a, b) => b.price - a.price);
    return list;
  }, [filteredProducts, sortOrder]);

  const toggleFilter = (key: keyof Filters, value: string) => {
    const current = filters[key];
    if (Array.isArray(current)) {
      const next = current.includes(value) 
        ? current.filter(v => v !== value) 
        : [...current, value];
      onFiltersChange({ ...filters, [key]: next });
    } else {
      onFiltersChange({ ...filters, [key]: value });
    }
  };

  const brands = Array.from(new Set(products.map(p => p.brand)));
  const genders = ["Masculino", "Feminino", "Kids"];
  const styles = Array.from(new Set(products.map(p => p.style)));

  return (
    <div className="container mx-auto px-4 py-8 bg-white dark:bg-[#121212]">
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar Filters */}
        <aside className="w-full lg:w-1/4">
          <div className="sticky top-28 bg-gray-50 dark:bg-gray-900/50 p-6 rounded-2xl border border-gray-200 dark:border-gray-800">
            <h2 className="text-xl font-bold uppercase mb-6 font-display">Filtros</h2>

            <div className="space-y-8">
              {/* Category */}
              <div>
                <h3 className="font-bold text-sm uppercase mb-3">Categoria</h3>
                <div className="space-y-2">
                  {["Todos", "Tênis", "Roupas", "Artigos Esportivos", "Life Style", "Suplementos"].map(cat => (
                    <button 
                      key={cat} 
                      onClick={() => onFiltersChange({ ...filters, category: cat })}
                      className={`block text-sm transition-colors ${filters.category === cat ? 'text-brand-yellow font-bold' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>

              {/* Brand */}
              <div>
                <h3 className="font-bold text-sm uppercase mb-3">Marca</h3>
                <div className="space-y-2">
                  {brands.map(brand => (
                    <label key={brand} className="flex items-center gap-2 cursor-pointer group">
                      <input 
                        type="checkbox" 
                        checked={filters.brand.includes(brand)}
                        onChange={() => toggleFilter('brand', brand)}
                        className="rounded border-gray-300 text-brand-yellow focus:ring-brand-yellow" 
                      />
                      <span className="text-sm text-gray-500 group-hover:text-black dark:group-hover:text-white transition-colors">{brand}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Gender */}
              <div>
                <h3 className="font-bold text-sm uppercase mb-3">Gênero</h3>
                <div className="space-y-2">
                  {genders.map(gender => (
                    <label key={gender} className="flex items-center gap-2 cursor-pointer group">
                      <input 
                        type="checkbox" 
                        checked={filters.gender.includes(gender)}
                        onChange={() => toggleFilter('gender', gender)}
                        className="rounded border-gray-300 text-brand-yellow focus:ring-brand-yellow" 
                      />
                      <span className="text-sm text-gray-500 group-hover:text-black dark:group-hover:text-white transition-colors">{gender}</span>
                    </label>
                  ))}
                </div>
              </div>

               {/* Style */}
               <div>
                <h3 className="font-bold text-sm uppercase mb-3">Estilo</h3>
                <div className="space-y-2">
                  {styles.map(style => (
                    <label key={style} className="flex items-center gap-2 cursor-pointer group">
                      <input 
                        type="checkbox" 
                        checked={filters.style.includes(style)}
                        onChange={() => toggleFilter('style', style)}
                        className="rounded border-gray-300 text-brand-yellow focus:ring-brand-yellow" 
                      />
                      <span className="text-sm text-gray-500 group-hover:text-black dark:group-hover:text-white transition-colors">{style}</span>
                    </label>
                  ))}
                </div>
              </div>

              <button 
                onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:''})}
                className="w-full bg-brand-yellow text-black font-bold py-3 rounded-full text-xs uppercase hover:bg-yellow-300 transition-colors"
              >
                Limpar Filtros
              </button>
            </div>
          </div>
        </aside>

        {/* Product Grid */}
        <main className="w-full lg:w-3/4">
          <div className="flex justify-between items-center mb-8 bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl border border-gray-200 dark:border-gray-800">
             <p className="text-sm font-bold">{sortedProducts.length} Produtos Encontrados</p>
             <div className="flex items-center gap-2">
               <span className="text-xs uppercase font-bold text-gray-500">Ordenar por:</span>
               <select 
                 value={sortOrder} 
                 onChange={(e) => setSortOrder(e.target.value)} 
                 className="bg-transparent font-bold text-sm focus:outline-none cursor-pointer border-none ring-0"
               >
                  <option value="featured">Destaques</option>
                  <option value="price-asc">Menor Preço</option>
                  <option value="price-desc">Maior Preço</option>
               </select>
             </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {sortedProducts.map(product => {
                const isWish = wishlistItems.some(i => i.id === product.id);
                const isOutOfStock = product.stock === 0;
                return (
                    <div 
                      key={product.id} 
                      className="group bg-white dark:bg-[#181818] rounded-2xl border border-gray-200 dark:border-gray-800 overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-300 flex flex-col h-full"
                      onClick={() => onNavigate('productDetail', product)}
                    >
                        <div className="relative aspect-[4/5] overflow-hidden bg-gray-100">
                            {isOutOfStock && (
                              <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10">
                                <span className="text-white font-bold uppercase tracking-widest border-2 border-white px-4 py-1">Esgotado</span>
                              </div>
                            )}
                            <img 
                              src={product.image} 
                              className={`w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ${isOutOfStock ? 'grayscale' : ''}`} 
                              alt={product.name} 
                            />
                            <button 
                                onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }} 
                                className="absolute top-4 right-4 p-2.5 bg-white/80 dark:bg-black/60 rounded-full backdrop-blur-md shadow-sm z-20 hover:scale-110 transition-transform"
                            >
                                {isWish ? <HeartIconSolid className="w-5 h-5 text-red-500" /> : <HeartIcon className="w-5 h-5 text-gray-900 dark:text-white" />}
                            </button>
                        </div>
                        <div className="p-5 flex flex-col flex-1">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-sm uppercase truncate pr-2 group-hover:text-brand-yellow transition-colors">{product.name}</h3>
                                <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                            </div>
                            <p className="text-xs text-gray-500 font-medium mb-4">{product.brand} | {product.style}</p>
                            <div className="mt-auto pt-4 border-t border-gray-100 dark:border-gray-800 flex justify-between items-center">
                              <p className="font-black text-xl text-black dark:text-white">R$ {product.price.toFixed(2)}</p>
                              <span className="text-[10px] font-black uppercase tracking-tighter text-brand-yellow">Ver Detalhes</span>
                            </div>
                        </div>
                    </div>
                );
            })}
          </div>

          {sortedProducts.length === 0 && (
            <div className="text-center py-20">
              <h3 className="text-2xl font-display uppercase mb-2">Nenhum produto encontrado</h3>
              <p className="text-gray-500">Tente ajustar seus filtros ou busca.</p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { LogoIcon, SearchIcon, HeartIcon, BagIcon, MenuIcon, CloseIcon } from './Icons';
import { Product, Filters } from '../data/products';

interface HeaderProps {
  products: Product[];
  currentPage: string;
  onNavigate: (page: string, product?: any, filters?: Partial<Filters>) => void;
  theme: 'light' | 'dark';
  onToggleTheme: () => void;
  cartCount: number;
  wishlistCount: number;
}

const Header: React.FC<HeaderProps> = ({ products, onNavigate, cartCount, wishlistCount }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      onNavigate('shop', undefined, { query: searchTerm });
      setSearchTerm('');
      setIsMobileMenuOpen(false);
    }
  };

  return (
    <>
      <header className="bg-white dark:bg-black border-b border-gray-200 dark:border-gray-800 sticky top-0 z-[100] w-full transition-all duration-300">
        <div className="container mx-auto px-4 lg:px-12 h-16 md:h-20 flex items-center justify-between gap-8">

          <div className="flex-shrink-0">
            <button onClick={() => onNavigate('home')} className="hover:opacity-70 transition-opacity">
              <LogoIcon className="h-6 md:h-8 w-auto text-black dark:text-white" />
            </button>
          </div>

          <nav className="hidden lg:flex items-center gap-8">
            <button onClick={() => onNavigate('shop')} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Lançamentos</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Masculino'] })} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Masculino</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Feminino'] })} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Feminino</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Kids'] })} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Kids</button>
            <button onClick={() => onNavigate('shop')} className="text-xs font-black text-brand-yellow uppercase tracking-widest">Ofertas</button>
          </nav>

          <div className="flex-1 max-w-sm relative hidden md:block">
            <form onSubmit={handleSearchSubmit} className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <SearchIcon className="h-4 w-4 text-gray-400" />
              </div>
              <input
                type="text"
                placeholder="O que você procura?"
                className="bg-gray-100 dark:bg-gray-900 text-sm w-full pl-9 pr-4 py-2 rounded-full border-none focus:ring-1 focus:ring-brand-yellow transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </form>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button onClick={() => onNavigate('wishlist')} className="relative p-2 hover:bg-gray-100 dark:hover:bg-gray-900 rounded-full transition-colors">
              <HeartIcon className="w-6 h-6" />
              {wishlistCount > 0 && <span className="absolute top-1 right-1 bg-brand-yellow text-black text-[9px] font-black h-4 w-4 rounded-full flex items-center justify-center">{wishlistCount}</span>}
            </button>
            <button onClick={() => onNavigate('cart')} className="relative p-2 hover:bg-gray-100 dark:hover:bg-gray-900 rounded-full transition-colors">
              <BagIcon className="w-6 h-6" />
              {cartCount > 0 && <span className="absolute top-1 right-1 bg-brand-yellow text-black text-[9px] font-black h-4 w-4 rounded-full flex items-center justify-center">{cartCount}</span>}
            </button>
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2">
              {isMobileMenuOpen ? <CloseIcon className="w-6 h-6" /> : <MenuIcon className="w-6 h-6" />}
            </button>
          </div>
        </div>
      </header>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[120] bg-white dark:bg-black pt-20 px-8 lg:hidden animate-fade-in overflow-y-auto">
           <form onSubmit={handleSearchSubmit} className="mb-8 relative">
              <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
              <input
                type="text"
                placeholder="Buscar produtos..."
                className="w-full pl-10 pr-4 py-3 bg-gray-100 dark:bg-gray-900 rounded-xl border-none"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
           </form>
           <nav className="flex flex-col gap-6 text-left">
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Lançamentos</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Masculino'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Masculino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Feminino'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Feminino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Kids'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Kids</button>
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter text-brand-yellow">Ofertas</button>

              <div className="mt-8 flex flex-col gap-4 pt-8 border-t border-gray-200 dark:border-gray-800">
                <button onClick={() => { onNavigate('wishlist'); setIsMobileMenuOpen(false); }} className="text-lg font-bold flex items-center gap-2"><HeartIcon className="w-5 h-5"/> Meus Favoritos</button>
                <button onClick={() => { onNavigate('help'); setIsMobileMenuOpen(false); }} className="text-lg font-bold">Ajuda & Suporte</button>
              </div>
           </nav>
        </div>
      )}
    </>
  );
};

