import React, { useState } from 'react';
import { LogoIcon, HeartIcon, BagIcon, MenuIcon, CloseIcon } from './Icons';
import { Product, Filters } from '../data/products';

interface HeaderProps {
  products: Product[];
  currentPage: string;
  onNavigate: (page: string, product?: any, filters?: Partial<Filters>) => void;
  theme: 'light' | 'dark';
  onToggleTheme: () => void;
  cartCount: number;
  wishlistCount: number;
}

const Header: React.FC<HeaderProps> = ({ onNavigate, cartCount, wishlistCount }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <>
      <header className="bg-white dark:bg-black border-b border-gray-200 dark:border-gray-800 sticky top-0 z-[100] w-full transition-all duration-300">
        <div className="container mx-auto px-4 lg:px-12 h-16 md:h-20 flex items-center justify-between">

          <div className="flex-shrink-0">
            <button onClick={() => onNavigate('home')} className="hover:opacity-80 transition-opacity">
              <LogoIcon className="h-auto" />
            </button>
          </div>

          <nav className="hidden lg:flex items-center gap-8">
            <button onClick={() => onNavigate('shop')} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Lançamentos</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Masculino'] })} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Masculino</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Feminino'] })} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Feminino</button>
            <button onClick={() => onNavigate('shop', undefined, { gender: ['Kids'] })} className="text-xs font-black hover:text-brand-yellow uppercase tracking-widest transition-colors">Kids</button>
            <button onClick={() => onNavigate('shop')} className="text-xs font-black text-brand-yellow uppercase tracking-widest">Ofertas</button>
            {/* Novo estilo do botão Seja VIP no desktop */}
            <button onClick={() => onNavigate('leadCapture')} className="hidden md:block text-xs font-black text-brand-yellow uppercase tracking-widest hover:opacity-80 transition-all">Seja VIP</button>
          </nav>

          <div className="flex items-center gap-2 md:gap-6">
            <button onClick={() => onNavigate('wishlist')} className="relative p-2 hover:bg-gray-100 dark:hover:bg-gray-900 rounded-full transition-colors" aria-label="Favoritos">
              <HeartIcon className="w-6 h-6" />
              {wishlistCount > 0 && <span className="absolute top-1 right-1 bg-brand-yellow text-black text-[9px] font-black h-4 w-4 rounded-full flex items-center justify-center">{wishlistCount}</span>}
            </button>
            <button onClick={() => onNavigate('cart')} className="relative p-2 hover:bg-gray-100 dark:hover:bg-gray-900 rounded-full transition-colors" aria-label="Carrinho">
              <BagIcon className="w-6 h-6" />
              {cartCount > 0 && <span className="absolute top-1 right-1 bg-brand-yellow text-black text-[9px] font-black h-4 w-4 rounded-full flex items-center justify-center">{cartCount}</span>}
            </button>
            <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="lg:hidden p-2">
              {isMobileMenuOpen ? <CloseIcon className="w-6 h-6" /> : <MenuIcon className="w-6 h-6" />}
            </button>
          </div>
        </div>
      </header>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[120] bg-white dark:bg-black pt-20 px-8 lg:hidden animate-fade-in overflow-y-auto">
           <nav className="flex flex-col gap-6 text-left">
              <button onClick={() => { onNavigate('leadCapture'); setIsMobileMenuOpen(false); }} className="w-full bg-brand-yellow text-black py-4 rounded-xl font-black text-xl uppercase italic">SEJA VIP / CADASTRE-SE</button>
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Lançamentos</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Masculino'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Masculino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Feminino'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Feminino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Kids'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-2">Kids</button>
              <button onClick={() => { onNavigate('shop'); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter text-brand-yellow">Ofertas</button>
           </nav>
        </div>
      )}
    </>
  );
};

