              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Masculino'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-3">Masculino</button>
              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Feminino'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-gray-100 dark:border-gray-800 pb-3">Feminino</button>
