              <button onClick={() => { onNavigate('shop', undefined, { gender: ['Kids'] }); setIsMobileMenuOpen(false); }} className="text-3xl font-black uppercase italic tracking-tighter border-b border-black/10 dark:border-white/10 pb-3">Kids</button>
