export default Header;

import React, { useState, useMemo } from 'react';
import { Product, Filters } from '../data/products';
import { HeartIcon, HeartIconSolid, StarIcon } from './Icons';

interface ShopProps {
  products: Product[];
  onNavigate: (page: string, product: Product) => void;
  wishlistItems: Product[];
  onToggleWishlist: (product: Product) => void;
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

const normalizeText = (text: string) => {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
};

const StarRatingDisplay: React.FC<{ rating: number; reviewCount: number }> = ({ rating, reviewCount }) => (
    <div className="flex flex-col items-end justify-start gap-1">
        <div className="flex items-center justify-end">
            {[...Array(5)].map((_, i) => (
                <StarIcon key={i} className={`w-3.5 h-3.5 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-gray-300 dark:text-gray-600'}`} />
            ))}
        </div>
        <span className="text-xs text-gray-500 dark:text-gray-400 font-medium text-right leading-none whitespace-nowrap">
            ({reviewCount > 0 ? reviewCount : Math.floor(Math.random() * 20) + 1} avaliações)
        </span>
    </div>
);

export default function Shop({ products, onNavigate, wishlistItems, onToggleWishlist, filters, onFiltersChange }: ShopProps) {
  const [sortOrder, setSortOrder] = useState('featured');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
        const catMatch = filters.category === 'Todos' || p.category === filters.category;
        const brandMatch = filters.brand.length === 0 || filters.brand.includes(p.brand);
        const genderMatch = filters.gender.length === 0 || filters.gender.includes(p.gender);
        const styleMatch = filters.style.length === 0 || filters.style.includes(p.style);

        let queryMatch = true;
        if (filters.query) {
            const normalizedQuery = normalizeText(filters.query);
            queryMatch = normalizeText(p.name).includes(normalizedQuery) || 
                         normalizeText(p.brand).includes(normalizedQuery);
        }
        return catMatch && brandMatch && genderMatch && styleMatch && queryMatch;
    });
  }, [products, filters]);

  const sortedProducts = useMemo(() => {
    const list = [...filteredProducts];
    if (sortOrder === 'price-asc') return list.sort((a, b) => a.price - b.price);
    if (sortOrder === 'price-desc') return list.sort((a, b) => b.price - a.price);
    return list;
  }, [filteredProducts, sortOrder]);

  const toggleFilter = (key: keyof Filters, value: string) => {
    const current = filters[key];
    if (Array.isArray(current)) {
      const next = current.includes(value) 
        ? current.filter(v => v !== value) 
        : [...current, value];
      onFiltersChange({ ...filters, [key]: next });
    } else {
      onFiltersChange({ ...filters, [key]: value });
    }
  };

  const brands = Array.from(new Set(products.map(p => p.brand)));

  return (
    <div className="container mx-auto px-4 py-12 bg-brand-blue-gray dark:bg-[#121212]">
      <div className="flex flex-col lg:flex-row gap-12">
        {/* Sidebar Filters */}
        <aside className="w-full lg:w-1/4">
          <div className="sticky top-28 bg-white/50 dark:bg-gray-900/50 p-8 rounded-2xl border border-gray-200 dark:border-gray-800 backdrop-blur-sm">
            <h2 className="text-2xl font-bold uppercase mb-8 font-display tracking-tight">Filtros</h2>

            <div className="space-y-10">
              <div>
                <h3 className="font-bold text-sm uppercase mb-4 tracking-widest text-black dark:text-white">Categoria</h3>
                <div className="space-y-3">
                  {["Todos", "Tênis", "Roupas", "Artigos Esportivos", "Life Style", "Suplementos"].map(cat => (
                    <button 
                      key={cat} 
                      onClick={() => onFiltersChange({ ...filters, category: cat })}
                      className={`block text-sm transition-colors ${filters.category === cat ? 'text-brand-yellow font-black' : 'text-gray-500 hover:text-black dark:hover:text-white'}`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <h3 className="font-bold text-sm uppercase mb-4 tracking-widest text-black dark:text-white">Marca</h3>
                <div className="space-y-3">
                  {brands.map(brand => (
                    <label key={brand} className="flex items-center gap-3 cursor-pointer group">
                      <input 
                        type="checkbox" 
                        checked={filters.brand.includes(brand)}
                        onChange={() => toggleFilter('brand', brand)}
                        className="w-4 h-4 rounded border-gray-300 text-brand-yellow focus:ring-brand-yellow" 
                      />
                      <span className="text-sm font-medium text-gray-500 group-hover:text-black dark:group-hover:text-white transition-colors">{brand}</span>
                    </label>
                  ))}
                </div>
              </div>

              <button 
                onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:''})}
                className="w-full bg-brand-yellow text-black font-black py-4 rounded-full text-xs uppercase hover:scale-105 transition-all shadow-md"
              >
                Limpar Filtros
              </button>
            </div>
          </div>
        </aside>

        {/* Product Grid */}
        <main className="w-full lg:w-3/4">
          <div className="flex justify-between items-center mb-10 bg-white/50 dark:bg-gray-900/50 p-6 rounded-xl border border-gray-200 dark:border-gray-800 backdrop-blur-sm">
             <p className="text-base font-bold text-black dark:text-white">{sortedProducts.length} Produtos Encontrados</p>
             <div className="flex items-center gap-3">
               <span className="text-[10px] uppercase font-black text-gray-400 tracking-widest">Ordenar por:</span>
               <select 
                 value={sortOrder} 
                 onChange={(e) => setSortOrder(e.target.value)} 
                 className="bg-transparent font-bold text-sm focus:outline-none cursor-pointer border-none ring-0 text-black dark:text-white"
               >
                  <option value="featured">Destaques</option>
                  <option value="price-asc">Menor Preço</option>
                  <option value="price-desc">Maior Preço</option>
               </select>
             </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {sortedProducts.map(product => {
                const isWish = wishlistItems.some(i => i.id === product.id);
                const isOutOfStock = product.stock === 0;
                return (
                    <div 
                      key={product.id} 
                      className="group bg-white dark:bg-[#181818] rounded-2xl border border-gray-100 dark:border-gray-800 overflow-hidden cursor-pointer shadow-sm hover:shadow-2xl transition-all duration-500 flex flex-col h-full"
                      onClick={() => onNavigate('productDetail', product)}
                    >
                        <div className="relative aspect-[4/5] overflow-hidden bg-gray-100 dark:bg-gray-800">
                            {isOutOfStock && (
                              <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10">
                                <span className="text-white font-bold uppercase tracking-widest border-2 border-white px-6 py-2">Esgotado</span>
                              </div>
                            )}
                            <img 
                              src={product.image} 
                              className={`w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ${isOutOfStock ? 'grayscale opacity-80' : ''}`} 
                              alt={product.name} 
                            />
                            <button 
                                onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }} 
                                className="absolute top-4 right-4 p-3 bg-white/90 dark:bg-black/80 rounded-full backdrop-blur-md shadow-lg z-20 hover:scale-110 transition-transform"
                            >
                                {isWish ? <HeartIconSolid className="w-6 h-6 text-red-500" /> : <HeartIcon className="w-6 h-6 text-gray-900 dark:text-white" />}
                            </button>
                        </div>
                        <div className="p-6 flex flex-col flex-1">
                            <div className="flex justify-between items-start mb-4">
                                <h3 className="font-black text-[13px] uppercase truncate pr-3 group-hover:text-brand-yellow transition-colors tracking-tight">{product.name}</h3>
                                <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                            </div>
                            <p className="text-[10px] text-gray-400 font-bold mb-6 tracking-widest uppercase">{product.brand} | {product.style}</p>
                            <div className="mt-auto pt-6 border-t border-gray-100 dark:border-gray-800 flex justify-between items-center">
                              <p className="font-black text-2xl text-black dark:text-white">R$ {product.price.toFixed(2)}</p>
                              <span className="text-[10px] font-black uppercase tracking-widest text-brand-yellow">Ver Detalhes</span>
                            </div>
                        </div>
                    </div>
                );
            })}
          </div>
        </main>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductShowcase from './components/ProductShowcase';
import FeaturedCategories from './components/FeaturedCategories';
import VideoAction from './components/VideoAction';
import Spotlight from './components/Spotlight';
import FeaturedProducts from './components/FeaturedProducts';
import Footer from './components/Footer';
import Cart from './components/Cart';
import ProductDetail from './components/ProductDetail';
import Shop from './components/Shop';
import Checkout from './components/Checkout';
import OrderConfirmation from './components/OrderConfirmation';
import Wishlist from './components/Wishlist';
import Help from './components/Help';
import Login from './components/Login';
import LeadCapture from './components/LeadCapture';
import VideoModal from './components/VideoModal';
import QuickViewModal from './components/QuickViewModal';
import { Product, CartItem, Order, Filters, products } from './data/products';
import { CheckCircleIcon, HeartIconSolid, ExclamationCircleIcon } from './components/Icons';

const Toast = ({ message, icon }: { message: string, icon: 'success' | 'heart' | 'error' }) => (
  <div className="fixed bottom-32 md:bottom-20 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-3 bg-black dark:bg-white text-white dark:text-black py-3 px-6 rounded-full shadow-2xl animate-fade-in border border-brand-yellow/30">
    {icon === 'success' && <CheckCircleIcon className="w-6 h-6 text-brand-yellow" />}
    {icon === 'heart' && <HeartIconSolid className="w-6 h-6 text-red-500" />}
    {icon === 'error' && <ExclamationCircleIcon className="w-6 h-6 text-red-500" />}
    <span className="font-semibold text-sm uppercase tracking-wider">{message}</span>
  </div>
);

export default function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [quickViewProduct, setQuickViewProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [wishlistItems, setWishlistItems] = useState<Product[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [completedOrder, setCompletedOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string; icon: 'success' | 'heart' | 'error' } | null>(null);
  const [isVideoModalOpen, setIsVideoModalOpen] = useState(false);
  const [currentVideoUrl, setCurrentVideoUrl] = useState('');
  const [activeFilters, setActiveFilters] = useState<Filters>({
    category: 'Todos',
    brand: [],
    gender: [],
    style: [],
    query: '',
  });

  useEffect(() => {
    document.documentElement.classList.remove('light', 'dark');
    document.documentElement.classList.add(theme);
  }, [theme]);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const navigateTo = (page: string, product?: Product, filters?: Partial<Filters>) => {
    if (filters) setActiveFilters(prev => ({ ...prev, ...filters }));
    if (page === 'productDetail' && product) setSelectedProduct(product);
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddToCart = (product: Product, quantity: number, size: string, color: string) => {
    const cartItemId = `${product.id}-${size}-${color}`;
    setCartItems(prev => {
      const existing = prev.find(item => item.cartItemId === cartItemId);
      if (existing) {
        return prev.map(item => item.cartItemId === cartItemId ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity, selectedSize: size, selectedColor: color, cartItemId }];
    });
    setToast({ message: `${product.name} no carrinho!`, icon: 'success' });
  };

  const handleToggleWishlist = (product: Product) => {
    setWishlistItems(prev => {
      const exists = prev.some(item => item.id === product.id);
      if (exists) {
        setToast({ message: 'Removido dos favoritos', icon: 'heart' });
        return prev.filter(item => item.id !== product.id);
      }
      setToast({ message: 'Adicionado aos favoritos!', icon: 'heart' });
      return [...prev, product];
    });
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'shop': return <Shop products={products} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} filters={activeFilters} onFiltersChange={setActiveFilters} />;
      case 'cart': return <Cart cartItems={cartItems} onContinueShopping={() => navigateTo('shop')} onQuantityChange={(id, d) => setCartItems(prev => prev.map(item => item.cartItemId === id ? { ...item, quantity: Math.max(1, item.quantity + d) } : item))} onRemoveItem={id => setCartItems(prev => prev.filter(item => item.cartItemId !== id))} onCheckout={() => navigateTo('checkout')} />;
      case 'productDetail': return selectedProduct ? <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} allProducts={products} onNavigate={navigateTo} /> : null;
      case 'checkout': return <Checkout cartItems={cartItems} onPlaceOrder={(details) => { setCompletedOrder({ id: `RI-${Date.now()}`, items: cartItems, total: cartItems.reduce((a, b) => a + b.price * b.quantity, 0), customer: details }); setCartItems([]); navigateTo('orderConfirmation'); }} />;
      case 'orderConfirmation': return completedOrder ? <OrderConfirmation order={completedOrder} onContinueShopping={() => navigateTo('shop')} /> : null;
      case 'wishlist': return <Wishlist wishlistItems={wishlistItems} onNavigate={navigateTo} onToggleWishlist={handleToggleWishlist} onAddToCart={handleAddToCart} />;
      case 'help': return <Help />;
      case 'login': return <Login />;
      case 'leadCapture': return <LeadCapture onNavigate={() => navigateTo('home')} />;
      default: return (
        <>
          <Hero />
          <ProductShowcase products={products} onNavigate={navigateTo} />
          <FeaturedCategories onNavigate={navigateTo} />
          <VideoAction onOpenVideo={(url) => { setCurrentVideoUrl(url); setIsVideoModalOpen(true); }} />
          <Spotlight onNavigate={navigateTo} />
          <FeaturedProducts products={products.slice(0, 3)} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} />
        </>
      );
    }
  };

  return (
    <div className="min-h-screen bg-brand-mediterranean dark:bg-[#121212] text-gray-900 dark:text-white transition-colors duration-300 font-sans overflow-x-hidden">
      <Header 
        products={products} 
        currentPage={currentPage} 
        onNavigate={navigateTo} 
        theme={theme} 
        onToggleTheme={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} 
        cartCount={cartItems.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlistItems.length} 
      />

      <main className="min-h-[calc(100vh-160px)]">{renderContent()}</main>

      <Footer onNavigate={navigateTo} />

      {toast && <Toast message={toast.message} icon={toast.icon} />}

      {isVideoModalOpen && <VideoModal videoUrl={currentVideoUrl} onClose={() => setIsVideoModalOpen(false)} />}

      {quickViewProduct && (
        <QuickViewModal 
          product={quickViewProduct} 
          onClose={() => setQuickViewProduct(null)} 
          onAddToCart={handleAddToCart} 
          onNavigateToProduct={(p) => { setQuickViewProduct(null); navigateTo('productDetail', p); }} 
        />
      )}
    </div>
  );
}

