import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import ProductShowcase from './components/ProductShowcase';
import FeaturedCategories from './components/FeaturedCategories';
import VideoAction from './components/VideoAction';
import Spotlight from './components/Spotlight';
import FeaturedProducts from './components/FeaturedProducts';
import Footer from './components/Footer';
import Cart from './components/Cart';
import ProductDetail from './components/ProductDetail';
import Shop from './components/Shop';
import Checkout from './components/Checkout';
import OrderConfirmation from './components/OrderConfirmation';
import Wishlist from './components/Wishlist';
import Help from './components/Help';
import Login from './components/Login';
import LeadCapture from './components/LeadCapture';
import VideoModal from './components/VideoModal';
import QuickViewModal from './components/QuickViewModal';
import { Product, CartItem, Order, Filters, products } from './data/products';
import { CheckCircleIcon, HeartIconSolid, ExclamationCircleIcon } from './components/Icons';

const Toast = ({ message, icon }: { message: string, icon: 'success' | 'heart' | 'error' }) => (
  <div className="fixed bottom-32 md:bottom-20 left-1/2 -translate-x-1/2 z-[100] flex items-center gap-3 bg-brand-naval-dark border border-brand-yellow/30 text-white py-3 px-6 rounded-full shadow-2xl animate-fade-in backdrop-blur-md">
    {icon === 'success' && <CheckCircleIcon className="w-6 h-6 text-brand-yellow" />}
    {icon === 'heart' && <HeartIconSolid className="w-6 h-6 text-red-500" />}
    {icon === 'error' && <ExclamationCircleIcon className="w-6 h-6 text-red-500" />}
    <span className="font-semibold text-sm uppercase tracking-wider">{message}</span>
  </div>
);

export default function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [quickViewProduct, setQuickViewProduct] = useState<Product | null>(null);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [wishlistItems, setWishlistItems] = useState<Product[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  const [completedOrder, setCompletedOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string; icon: 'success' | 'heart' | 'error' } | null>(null);
  const [isVideoModalOpen, setIsVideoModalOpen] = useState(false);
  const [currentVideoUrl, setCurrentVideoUrl] = useState('');
  const [activeFilters, setActiveFilters] = useState<Filters>({
    category: 'Todos',
    brand: [],
    gender: [],
    style: [],
    query: '',
  });

  useEffect(() => {
    document.documentElement.classList.remove('light', 'dark');
    document.documentElement.classList.add(theme);
  }, [theme]);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const navigateTo = (page: string, product?: Product, filters?: Partial<Filters>) => {
    if (filters) setActiveFilters(prev => ({ ...prev, ...filters }));
    if (page === 'productDetail' && product) setSelectedProduct(product);
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddToCart = (product: Product, quantity: number, size: string, color: string) => {
    const cartItemId = `${product.id}-${size}-${color}`;
    setCartItems(prev => {
      const existing = prev.find(item => item.cartItemId === cartItemId);
      if (existing) {
        return prev.map(item => item.cartItemId === cartItemId ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity, selectedSize: size, selectedColor: color, cartItemId }];
    });
    setToast({ message: `${product.name} no carrinho!`, icon: 'success' });
  };

  const handleToggleWishlist = (product: Product) => {
    setWishlistItems(prev => {
      const exists = prev.some(item => item.id === product.id);
      if (exists) {
        setToast({ message: 'Removido dos favoritos', icon: 'heart' });
        return prev.filter(item => item.id !== product.id);
      }
      setToast({ message: 'Adicionado aos favoritos!', icon: 'heart' });
      return [...prev, product];
    });
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'shop': return <Shop products={products} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} filters={activeFilters} onFiltersChange={setActiveFilters} />;
      case 'cart': return <Cart cartItems={cartItems} onContinueShopping={() => navigateTo('shop')} onQuantityChange={(id, d) => setCartItems(prev => prev.map(item => item.cartItemId === id ? { ...item, quantity: Math.max(1, item.quantity + d) } : item))} onRemoveItem={id => setCartItems(prev => prev.filter(item => item.cartItemId !== id))} onCheckout={() => navigateTo('checkout')} />;
      case 'productDetail': return selectedProduct ? <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} allProducts={products} onNavigate={navigateTo} /> : null;
      case 'checkout': return <Checkout cartItems={cartItems} onPlaceOrder={(details) => { setCompletedOrder({ id: `RI-${Date.now()}`, items: cartItems, total: cartItems.reduce((a, b) => a + b.price * b.quantity, 0), customer: details }); setCartItems([]); navigateTo('orderConfirmation'); }} />;
      case 'orderConfirmation': return completedOrder ? <OrderConfirmation order={completedOrder} onContinueShopping={() => navigateTo('shop')} /> : null;
      case 'wishlist': return <Wishlist wishlistItems={wishlistItems} onNavigate={navigateTo} onToggleWishlist={handleToggleWishlist} onAddToCart={handleAddToCart} />;
      case 'help': return <Help />;
      case 'login': return <Login />;
      case 'leadCapture': return <LeadCapture onNavigate={() => navigateTo('home')} />;
      default: return (
        <>
          <Hero />
          <ProductShowcase products={products} onNavigate={navigateTo} />
          <FeaturedCategories onNavigate={navigateTo} />
          <VideoAction onOpenVideo={(url) => { setCurrentVideoUrl(url); setIsVideoModalOpen(true); }} />
          <Spotlight onNavigate={navigateTo} />
          <FeaturedProducts products={products.slice(0, 3)} onNavigate={navigateTo} wishlistItems={wishlistItems} onToggleWishlist={handleToggleWishlist} />
        </>
      );
    }
  };

  return (
    <div className="min-h-screen bg-brand-off-white dark:bg-brand-naval-dark text-brand-naval dark:text-brand-off-white transition-colors duration-300 font-sans overflow-x-hidden">
      <Header 
        products={products} 
        currentPage={currentPage} 
        onNavigate={navigateTo} 
        theme={theme} 
        onToggleTheme={() => setTheme(t => t === 'dark' ? 'light' : 'dark')} 
        cartCount={cartItems.reduce((a, b) => a + b.quantity, 0)} 
        wishlistCount={wishlistItems.length} 
      />

      <main className="min-h-[calc(100vh-160px)]">{renderContent()}</main>

      <Footer onNavigate={navigateTo} />

      {toast && <Toast message={toast.message} icon={toast.icon} />}

      {isVideoModalOpen && <VideoModal videoUrl={currentVideoUrl} onClose={() => setIsVideoModalOpen(false)} />}

      {quickViewProduct && (
        <QuickViewModal 
          product={quickViewProduct} 
          onClose={() => setQuickViewProduct(null)} 
          onAddToCart={handleAddToCart} 
          onNavigateToProduct={(p) => { setQuickViewProduct(null); navigateTo('productDetail', p); }} 
        />
      )}
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { Product, Filters } from '../data/products';
import { HeartIcon, HeartIconSolid, StarIcon } from './Icons';

interface ShopProps {
  products: Product[];
  onNavigate: (page: string, product: Product) => void;
  wishlistItems: Product[];
  onToggleWishlist: (product: Product) => void;
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

const normalizeText = (text: string) => {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
};

const StarRatingDisplay: React.FC<{ rating: number; reviewCount: number }> = ({ rating, reviewCount }) => (
    <div className="flex flex-col items-end justify-start gap-1">
        <div className="flex items-center justify-end">
            {[...Array(5)].map((_, i) => (
                <StarIcon key={i} className={`w-3.5 h-3.5 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-brand-naval/30 dark:text-gray-600'}`} />
            ))}
        </div>
        <span className="text-xs text-brand-naval/60 dark:text-gray-400 font-medium text-right leading-none whitespace-nowrap">
            ({reviewCount > 0 ? reviewCount : Math.floor(Math.random() * 20) + 1} avaliações)
        </span>
    </div>
);

export default function Shop({ products, onNavigate, wishlistItems, onToggleWishlist, filters, onFiltersChange }: ShopProps) {
  const [sortOrder, setSortOrder] = useState('featured');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
        const catMatch = filters.category === 'Todos' || p.category === filters.category;
        const brandMatch = filters.brand.length === 0 || filters.brand.includes(p.brand);
        const genderMatch = filters.gender.length === 0 || filters.gender.includes(p.gender);
        const styleMatch = filters.style.length === 0 || filters.style.includes(p.style);

        let queryMatch = true;
        if (filters.query) {
            const normalizedQuery = normalizeText(filters.query);
            queryMatch = normalizeText(p.name).includes(normalizedQuery) || 
                         normalizeText(p.brand).includes(normalizedQuery);
        }
        return catMatch && brandMatch && genderMatch && styleMatch && queryMatch;
    });
  }, [products, filters]);

  const sortedProducts = useMemo(() => {
    const list = [...filteredProducts];
    if (sortOrder === 'price-asc') return list.sort((a, b) => a.price - b.price);
    if (sortOrder === 'price-desc') return list.sort((a, b) => b.price - a.price);
    return list;
  }, [filteredProducts, sortOrder]);

  const toggleFilter = (key: keyof Filters, value: string) => {
    const current = filters[key];
    if (Array.isArray(current)) {
      const next = current.includes(value) 
        ? current.filter(v => v !== value) 
        : [...current, value];
      onFiltersChange({ ...filters, [key]: next });
    } else {
      onFiltersChange({ ...filters, [key]: value });
    }
  };

  const brands = Array.from(new Set(products.map(p => p.brand)));

  return (
    <div className="w-full bg-brand-off-white dark:bg-brand-naval-dark transition-colors duration-300">
      <div className="container mx-auto px-4 py-12">
        <div className="flex flex-col lg:flex-row gap-12">
          {/* Sidebar Filters */}
          <aside className="w-full lg:w-1/4">
            <div className="sticky top-28 bg-brand-surface-light dark:bg-brand-naval-light/20 p-8 rounded-2xl border border-brand-border-light dark:border-white/5 backdrop-blur-md shadow-lg">
              <h2 className="text-2xl font-bold uppercase mb-8 font-display tracking-tight text-brand-naval dark:text-brand-off-white">Filtros</h2>

              <div className="space-y-10">
                <div>
                  <h3 className="font-bold text-sm uppercase mb-4 tracking-widest text-brand-naval/70 dark:text-brand-yellow">Categoria</h3>
                  <div className="space-y-3">
                    {["Todos", "Tênis", "Roupas", "Artigos Esportivos", "Life Style", "Suplementos"].map(cat => (
                      <button 
                        key={cat} 
                        onClick={() => onFiltersChange({ ...filters, category: cat })}
                        className={`block text-sm transition-colors ${filters.category === cat ? 'text-brand-naval dark:text-brand-yellow font-black' : 'text-brand-naval/50 hover:text-brand-naval dark:text-gray-400 dark:hover:text-white'}`}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <h3 className="font-bold text-sm uppercase mb-4 tracking-widest text-brand-naval/70 dark:text-brand-yellow">Marca</h3>
                  <div className="space-y-3">
                    {brands.map(brand => (
                      <label key={brand} className="flex items-center gap-3 cursor-pointer group">
                        <input 
                          type="checkbox" 
                          checked={filters.brand.includes(brand)}
                          onChange={() => toggleFilter('brand', brand)}
                          className="w-4 h-4 rounded border-brand-border-light dark:border-white/10 bg-transparent text-brand-naval dark:text-brand-yellow focus:ring-brand-yellow" 
                        />
                        <span className="text-sm font-medium text-brand-naval/60 group-hover:text-brand-naval dark:text-gray-400 dark:group-hover:text-white transition-colors">{brand}</span>
                      </label>
                    ))}
                  </div>
                </div>

                <button 
                  onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:''})}
                  className="w-full bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-black py-4 rounded-full text-xs uppercase hover:scale-105 transition-all shadow-md"
                >
                  Limpar Filtros
                </button>
              </div>
            </div>
          </aside>

          {/* Product Grid */}
          <main className="w-full lg:w-3/4">
            <div className="flex justify-between items-center mb-10 bg-brand-surface-light dark:bg-brand-naval-light/10 p-6 rounded-xl border border-brand-border-light dark:border-white/5 backdrop-blur-md shadow-sm">
               <p className="text-base font-bold text-brand-naval dark:text-brand-off-white">{sortedProducts.length} Produtos Encontrados</p>
               <div className="flex items-center gap-3">
                 <span className="text-[10px] uppercase font-black text-brand-naval/40 dark:text-gray-400 tracking-widest">Ordenar por:</span>
                 <select 
                   value={sortOrder} 
                   onChange={(e) => setSortOrder(e.target.value)} 
                   className="bg-transparent font-bold text-sm focus:outline-none cursor-pointer border-none ring-0 text-brand-naval dark:text-brand-off-white"
                 >
                    <option value="featured">Destaques</option>
                    <option value="price-asc">Menor Preço</option>
                    <option value="price-desc">Maior Preço</option>
                 </select>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {sortedProducts.map(product => {
                  const isWish = wishlistItems.some(i => i.id === product.id);
                  const isOutOfStock = product.stock === 0;
                  return (
                      <div 
                        key={product.id} 
                        className="group bg-brand-surface-light/40 dark:bg-brand-naval-light/5 rounded-2xl border border-brand-border-light dark:border-white/5 overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-500 flex flex-col h-full hover:bg-brand-surface-light"
                        onClick={() => onNavigate('productDetail', product)}
                      >
                          <div className="relative aspect-[4/5] overflow-hidden bg-brand-surface-light dark:bg-black/20">
                              {isOutOfStock && (
                                <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10">
                                  <span className="text-white font-bold uppercase tracking-widest border-2 border-white px-6 py-2">Esgotado</span>
                                </div>
                              )}
                              <img 
                                src={product.image} 
                                className={`w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ${isOutOfStock ? 'grayscale opacity-80' : ''}`} 
                                alt={product.name} 
                              />
                              <button 
                                  onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }} 
                                  className="absolute top-4 right-4 p-3 bg-brand-off-white/80 dark:bg-black/40 rounded-full backdrop-blur-md shadow-lg z-20 hover:scale-110 transition-transform text-brand-naval dark:text-brand-off-white"
                              >
                                  {isWish ? <HeartIconSolid className="w-6 h-6 text-red-500" /> : <HeartIcon className="w-6 h-6" />}
                              </button>
                          </div>
                          <div className="p-6 flex flex-col flex-1">
                              <div className="flex justify-between items-start mb-4">
                                  <h3 className="font-black text-[13px] uppercase truncate pr-3 group-hover:text-brand-naval dark:group-hover:text-brand-yellow transition-colors tracking-tight text-brand-naval dark:text-white">{product.name}</h3>
                                  <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                              </div>
                              <p className="text-[10px] text-brand-naval/50 dark:text-gray-400 font-bold mb-6 tracking-widest uppercase">{product.brand} | {product.style}</p>
                              <div className="mt-auto pt-6 border-t border-brand-border-light dark:border-white/5 flex justify-between items-center">
                                <p className="font-black text-2xl text-brand-naval dark:text-white">R$ {product.price.toFixed(2)}</p>
                                <span className="text-[10px] font-black uppercase tracking-widest text-brand-naval dark:text-brand-yellow">Ver Detalhes</span>
                              </div>
                          </div>
                      </div>
                  );
              })}
            </div>
          </main>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { TrashIcon, PlusIcon, MinusIcon } from './Icons';
import { CartItem } from '../data/products';

interface CartProps {
  cartItems: CartItem[];
  onContinueShopping: () => void;
  onQuantityChange: (cartItemId: string, delta: number) => void;
  onRemoveItem: (cartItemId: string) => void;
  onCheckout: () => void;
}

const Cart: React.FC<CartProps> = ({ cartItems, onContinueShopping, onQuantityChange, onRemoveItem, onCheckout }) => {

  const subtotal = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const shipping = subtotal > 0 ? 15.00 : 0;
  const total = subtotal + shipping;

  if (cartItems.length === 0) {
    return (
      <div className="container mx-auto px-4 py-20 text-center min-h-[60vh] flex flex-col items-center justify-center">
        <h1 className="text-4xl font-display uppercase mb-4 text-brand-naval dark:text-brand-off-white">Seu Carrinho está Vazia</h1>
        <p className="text-brand-naval/60 dark:text-gray-400 mb-8">Parece que você ainda não adicionou nada. Que tal explorar nossos produtos?</p>
        <button 
          onClick={onContinueShopping}
          className="bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-semibold py-3 px-8 rounded-full hover:scale-105 transition-all shadow-lg"
        >
          Explorar Produtos
        </button>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-12 md:py-20">
      <h1 className="text-4xl md:text-5xl font-display uppercase mb-8 text-brand-naval dark:text-brand-off-white">Seu Carrinho</h1>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          {cartItems.map(item => (
            <div key={item.cartItemId} className="flex items-start bg-brand-surface-light dark:bg-brand-naval-light/10 p-4 rounded-lg gap-4 border border-brand-border-light dark:border-white/5">
              <img src={item.image} alt={item.name} className="w-24 h-24 md:w-32 md:h-32 object-cover rounded-md" onContextMenu={(e) => e.preventDefault()} />
              <div className="flex-1">
                <div className="flex justify-between items-start">
                  <div>
                    <h2 className="font-bold text-lg text-brand-naval dark:text-white">{item.name}</h2>
                    <p className="text-sm text-brand-naval/60 dark:text-gray-400">{item.desc}</p>
                    <p className="text-sm text-brand-naval/60 dark:text-gray-400">Cor: {item.selectedColor}</p>
                    <p className="text-sm text-brand-naval/60 dark:text-gray-400">Tamanho: {item.selectedSize}</p>
                  </div>
                  <p className="font-semibold text-lg whitespace-nowrap text-brand-naval dark:text-white">R$ {(item.price * item.quantity).toFixed(2)}</p>
                </div>
                <div className="flex items-center justify-between mt-4">
                  <div className="flex items-center gap-2 bg-brand-off-white dark:bg-brand-naval-dark rounded-full p-1 border border-brand-border-light dark:border-white/10">
                    <button onClick={() => onQuantityChange(item.cartItemId, -1)} className="p-1.5 rounded-full hover:bg-brand-border-light dark:hover:bg-gray-700 text-brand-naval dark:text-white"><MinusIcon className="w-5 h-5" /></button>
                    <span className="px-3 font-semibold text-brand-naval dark:text-white">{item.quantity}</span>
                    <button onClick={() => onQuantityChange(item.cartItemId, 1)} className="p-1.5 rounded-full hover:bg-brand-border-light dark:hover:bg-gray-700 text-brand-naval dark:text-white"><PlusIcon className="w-5 h-5" /></button>
                  </div>
                  <button onClick={() => onRemoveItem(item.cartItemId)} className="text-brand-naval/40 dark:text-gray-400 hover:text-red-500 transition-colors">
                    <TrashIcon className="w-6 h-6" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="lg:col-span-1">
          <div className="bg-brand-surface-light dark:bg-brand-naval-light/10 p-6 rounded-lg sticky top-24 border border-brand-border-light dark:border-white/5 shadow-xl">
            <h2 className="text-2xl font-bold uppercase mb-4 text-brand-naval dark:text-white">Resumo do Pedido</h2>
            <div className="space-y-3 text-brand-naval/70 dark:text-gray-300">
              <div className="flex justify-between">
                <span>Subtotal</span>
                <span>R$ {subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between">
                <span>Frete</span>
                <span>R$ {shipping.toFixed(2)}</span>
              </div>
               <div className="flex justify-between text-brand-naval dark:text-white font-bold text-lg pt-4 border-t border-brand-border-light dark:border-gray-700">
                <span>Total</span>
                <span>R$ {total.toFixed(2)}</span>
              </div>
            </div>
            <button 
                onClick={onCheckout}
                className="w-full mt-6 bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-semibold py-3 rounded-full hover:scale-105 transition-all shadow-md">
              Finalizar Compra
            </button>
             <button 
                onClick={onContinueShopping}
                className="w-full mt-3 bg-brand-border-light text-brand-naval font-semibold py-3 rounded-full hover:bg-brand-off-white transition-all dark:bg-gray-200 dark:text-black"
            >
                Continuar Comprando
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Cart;

import React, { useState, useRef, useEffect } from 'react';
import { Product } from '../data/products';
import { PlusIcon, MinusIcon, HeartIcon, HeartIconSolid, StarIcon } from './Icons';

interface ProductDetailProps {
  product: Product;
  onAddToCart: (product: Product, quantity: number, size: string, color: string) => void;
  wishlistItems: Product[];
  onToggleWishlist: (product: Product) => void;
  allProducts: Product[];
  onNavigate: (page: string, product: Product) => void;
}

const StarRating: React.FC<{ rating: number, totalReviews: number }> = ({ rating, totalReviews }) => (
  <div className="flex flex-col items-end gap-1">
    <div className="flex items-center">
      {[...Array(5)].map((_, i) => (
        <StarIcon key={i} className={`w-5 h-5 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-brand-naval/20 dark:text-gray-600'}`} />
      ))}
    </div>
    <span className="text-sm text-brand-naval/50 dark:text-gray-400 font-medium whitespace-nowrap">
      ({totalReviews > 0 ? totalReviews : Math.floor(Math.random() * 20) + 1} avaliações)
    </span>
  </div>
);

const ReviewForm: React.FC<{ onSubmit: (review: { rating: number, comment: string, author: string }) => void }> = ({ onSubmit }) => {
    const [rating, setRating] = useState(0);
    const [hoverRating, setHoverRating] = useState(0);
    const [comment, setComment] = useState('');
    const [author, setAuthor] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (rating > 0 && comment && author) {
            onSubmit({ rating, comment, author });
            setSubmitted(true);
        }
    };

    if (submitted) {
        return <p className="text-brand-yellow font-semibold text-lg">Obrigado pela sua avaliação!</p>;
    }

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div>
                <label className="block text-lg font-bold mb-2 text-brand-naval dark:text-white">Sua Avaliação</label>
                <div className="flex items-center mt-1 gap-1">
                    {[1, 2, 3, 4, 5].map(star => (
                        <button
                            key={star}
                            type="button"
                            onMouseEnter={() => setHoverRating(star)}
                            onMouseLeave={() => setHoverRating(0)}
                            onClick={() => setRating(star)}
                            className="text-brand-naval/20 dark:text-gray-600 hover:scale-110 transition-transform"
                        >
                            <StarIcon className={`w-8 h-8 transition-colors ${(hoverRating || rating) >= star ? 'text-brand-yellow' : ''}`} />
                        </button>
                    ))}
                </div>
            </div>
            <div>
                <label htmlFor="author" className="block text-lg font-bold mb-2 text-brand-naval dark:text-white">Seu Nome</label>
                <input type="text" id="author" value={author} onChange={e => setAuthor(e.target.value)} required className="w-full rounded-lg bg-brand-surface-light dark:bg-brand-naval-light/20 border-brand-border-light dark:border-white/10 focus:border-brand-yellow focus:bg-brand-off-white dark:focus:bg-black focus:ring-0 p-4 text-lg text-brand-naval dark:text-white placeholder-brand-naval/30" placeholder="Digite seu nome" />
            </div>
            <div>
                <label htmlFor="comment" className="block text-lg font-bold mb-2 text-brand-naval dark:text-white">Seu Comentário</label>
                <textarea id="comment" value={comment} onChange={e => setComment(e.target.value)} rows={4} required className="w-full rounded-lg bg-brand-surface-light dark:bg-brand-naval-light/20 border-brand-border-light dark:border-white/10 focus:border-brand-yellow focus:bg-brand-off-white dark:focus:bg-black focus:ring-0 p-4 text-lg text-brand-naval dark:text-white placeholder-brand-naval/30" placeholder="O que você achou do produto?"></textarea>
            </div>
            <button type="submit" className="bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-bold text-lg py-3 px-8 rounded-full hover:scale-105 transition-all shadow-md">
                Enviar Avaliação
            </button>
        </form>
    );
};


const ProductDetail: React.FC<ProductDetailProps> = ({ product, onAddToCart, wishlistItems, onToggleWishlist, allProducts, onNavigate }) => {
  const [selectedImage, setSelectedImage] = useState(product.gallery[0]);
  const [selectedSize, setSelectedSize] = useState(product.sizes[0]);
  const [selectedColor, setSelectedColor] = useState(product.colors[0]);
  const [quantity, setQuantity] = useState(1);
  const [allReviews, setAllReviews] = useState(product.reviews);
  const [isZooming, setIsZooming] = useState(false);
  const [bgPosition, setBgPosition] = useState('center');
  const imageContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedImage(product.gallery[0]);
    setSelectedSize(product.sizes[0]);
    setSelectedColor(product.colors[0]);
    setQuantity(1);
    setAllReviews(product.reviews);
  }, [product]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!imageContainerRef.current) return;
    const { left, top, width, height } = imageContainerRef.current.getBoundingClientRect();
    const x = e.clientX - left;
    const y = e.clientY - top;

    const bgX = (x / width) * 100;
    const bgY = (y / height) * 100;

    setBgPosition(`${bgX}% ${bgY}%`);
  };

  const handleAddToCartClick = () => {
    onAddToCart(product, quantity, selectedSize, selectedColor);
  };

  const handleReviewSubmit = (review: { rating: number, comment: string, author: string }) => {
    setAllReviews(prev => [...prev, review]);
  };

  const isWishlisted = wishlistItems.some(item => item.id === product.id);
  const isOutOfStock = product.stock === 0;

  const relatedProducts = allProducts
    .filter(p => p.category === product.category && p.id !== product.id)
    .slice(0, 4);

  return (
    <div className="container mx-auto px-4 py-12 md:py-20">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
        <div className="relative">
            <div 
              ref={imageContainerRef}
              className="relative overflow-hidden rounded-lg shadow-lg cursor-zoom-in mb-4 border border-brand-border-light dark:border-white/5"
              onMouseEnter={() => setIsZooming(true)}
              onMouseLeave={() => setIsZooming(false)}
              onMouseMove={handleMouseMove}
            >
              <img src={selectedImage} alt={product.name} className="w-full h-auto object-cover aspect-square" onContextMenu={(e) => e.preventDefault()} />
            </div>

            <div className="flex gap-2 overflow-x-auto pb-2 -mx-4 px-4 scrollbar-hide">
              {product.gallery.map((img, index) => (
                <button 
                  key={index} 
                  onClick={() => setSelectedImage(img)}
                  className={`flex-shrink-0 w-20 h-20 md:w-24 md:h-24 rounded-lg overflow-hidden border-2 transition-colors ${selectedImage === img ? 'border-brand-yellow' : 'border-transparent bg-brand-surface-light dark:bg-brand-naval-light/20'}`}
                >
                  <img src={img} alt={`${product.name} view ${index + 1}`} className="w-full h-full object-cover" onContextMenu={(e) => e.preventDefault()} />
                </button>
              ))}
            </div>

          <div 
            className={`hidden lg:block absolute left-full ml-8 top-0 w-full h-full bg-no-repeat border-2 border-brand-border-light dark:border-gray-700 rounded-lg shadow-2xl pointer-events-none transition-opacity duration-300 z-10 ${isZooming ? 'opacity-100' : 'opacity-0'}`}
            style={{
                backgroundImage: `url(${selectedImage})`,
                backgroundPosition: bgPosition,
                backgroundSize: '200%',
            }}
          />
        </div>

        <div>
          <div className="flex justify-between items-center w-full gap-4 mb-6 text-brand-naval dark:text-white">
              <h1 className="text-4xl md:text-5xl font-display uppercase leading-tight flex-1 text-left">
                  {product.name}
              </h1>
              <div className="flex-shrink-0 flex flex-col items-end min-w-[120px]">
                  <StarRating rating={product.rating} totalReviews={allReviews.length} />
              </div>
          </div>

          <p className="text-lg text-brand-naval/60 dark:text-gray-400 mt-2">{product.desc}</p>
          <p className="text-3xl font-bold mt-4 text-brand-naval dark:text-white">R$ {product.price.toFixed(2)}</p>

          <div className="mt-6">
            <h3 className="text-sm font-semibold uppercase tracking-wider text-brand-naval/70 dark:text-gray-300">Selecione a Cor</h3>
            <div className="flex items-center gap-3 mt-2">
              {product.colors.map(color => (
                <button 
                  key={color}
                  onClick={() => setSelectedColor(color)}
                  className={`px-4 py-2 rounded-full text-sm font-medium border-2 transition-colors ${selectedColor === color ? 'bg-brand-naval text-brand-off-white dark:bg-white dark:text-black border-transparent' : 'bg-transparent border-brand-border-light text-brand-naval/60 dark:border-gray-600 dark:text-gray-400'}`}
                >
                  {color}
                </button>
              ))}
            </div>
          </div>

          <div className="mt-6">
            <h3 className="text-sm font-semibold uppercase tracking-wider text-brand-naval/70 dark:text-gray-300">Selecione o Tamanho</h3>
            <div className="flex flex-wrap items-center gap-3 mt-2">
              {product.sizes.map(size => (
                <button 
                  key={size}
