                          </div>
                          <div className="p-6 flex flex-col flex-1">
                              <div className="flex justify-between items-start mb-4">
                                  <h3 className="font-black text-[13px] uppercase truncate pr-3 group-hover:text-brand-naval dark:group-hover:text-brand-yellow transition-colors tracking-tight text-brand-naval dark:text-white">{product.name}</h3>
                                  <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                              </div>
                              <p className="text-[10px] text-brand-naval/50 dark:text-gray-400 font-bold mb-6 tracking-widest uppercase">{product.brand} | {product.style}</p>
                              <div className="mt-auto pt-6 border-t border-brand-border-light dark:border-white/5 flex justify-between items-center">
                                <p className="font-black text-2xl text-brand-naval dark:text-white">R$ {product.price.toFixed(2)}</p>
