            <div>
                <label htmlFor="author" className="block text-lg font-bold mb-2 text-brand-naval dark:text-white">Seu Nome</label>
                <input type="text" id="author" value={author} onChange={e => setAuthor(e.target.value)} required className="w-full rounded-lg bg-brand-surface-light dark:bg-brand-naval-light/20 border-brand-border-light dark:border-white/10 focus:border-brand-yellow focus:bg-brand-off-white dark:focus:bg-black focus:ring-0 p-4 text-lg text-brand-naval dark:text-white placeholder-brand-naval/30" placeholder="Digite seu nome" />
            </div>
            <div>
                <label htmlFor="comment" className="block text-lg font-bold mb-2 text-brand-naval dark:text-white">Seu Comentário</label>
                <textarea id="comment" value={comment} onChange={e => setComment(e.target.value)} rows={4} required className="w-full rounded-lg bg-brand-surface-light dark:bg-brand-naval-light/20 border-brand-border-light dark:border-white/10 focus:border-brand-yellow focus:bg-brand-off-white dark:focus:bg-black focus:ring-0 p-4 text-lg text-brand-naval dark:text-white placeholder-brand-naval/30" placeholder="O que você achou do produto?"></textarea>
            </div>
            <button type="submit" className="bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-bold text-lg py-3 px-8 rounded-full hover:scale-105 transition-all shadow-md">
                Enviar Avaliação
            </button>
        </form>
    );
};


const ProductDetail: React.FC<ProductDetailProps> = ({ product, onAddToCart, wishlistItems, onToggleWishlist, allProducts, onNavigate }) => {
  const [selectedImage, setSelectedImage] = useState(product.gallery[0]);
  const [selectedSize, setSelectedSize] = useState(product.sizes[0]);
  const [selectedColor, setSelectedColor] = useState(product.colors[0]);
  const [quantity, setQuantity] = useState(1);
  const [allReviews, setAllReviews] = useState(product.reviews);
  const [isZooming, setIsZooming] = useState(false);
  const [bgPosition, setBgPosition] = useState('center');
  const imageContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setSelectedImage(product.gallery[0]);
    setSelectedSize(product.sizes[0]);
    setSelectedColor(product.colors[0]);
    setQuantity(1);
    setAllReviews(product.reviews);
  }, [product]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!imageContainerRef.current) return;
    const { left, top, width, height } = imageContainerRef.current.getBoundingClientRect();
    const x = e.clientX - left;
    const y = e.clientY - top;

    const bgX = (x / width) * 100;
    const bgY = (y / height) * 100;

    setBgPosition(`${bgX}% ${bgY}%`);
  };

  const handleAddToCartClick = () => {
    onAddToCart(product, quantity, selectedSize, selectedColor);
  };

  const handleReviewSubmit = (review: { rating: number, comment: string, author: string }) => {
    setAllReviews(prev => [...prev, review]);
  };

  const isWishlisted = wishlistItems.some(item => item.id === product.id);
  const isOutOfStock = product.stock === 0;

  const relatedProducts = allProducts
    .filter(p => p.category === product.category && p.id !== product.id)
    .slice(0, 4);

  return (
    <div className="container mx-auto px-4 py-12 md:py-20">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
        <div className="relative">
            <div 
              ref={imageContainerRef}
              className="relative overflow-hidden rounded-lg shadow-lg cursor-zoom-in mb-4 border border-brand-border-light dark:border-white/5"
              onMouseEnter={() => setIsZooming(true)}
              onMouseLeave={() => setIsZooming(false)}
              onMouseMove={handleMouseMove}
            >
              <img src={selectedImage} alt={product.name} className="w-full h-auto object-cover aspect-square" onContextMenu={(e) => e.preventDefault()} />
            </div>

            <div className="flex gap-2 overflow-x-auto pb-2 -mx-4 px-4 scrollbar-hide">
              {product.gallery.map((img, index) => (
                <button 
                  key={index} 
                  onClick={() => setSelectedImage(img)}
                  className={`flex-shrink-0 w-20 h-20 md:w-24 md:h-24 rounded-lg overflow-hidden border-2 transition-colors ${selectedImage === img ? 'border-brand-yellow' : 'border-transparent bg-brand-surface-light dark:bg-brand-naval-light/20'}`}
                >
                  <img src={img} alt={`${product.name} view ${index + 1}`} className="w-full h-full object-cover" onContextMenu={(e) => e.preventDefault()} />
                </button>
              ))}
            </div>

          <div 
            className={`hidden lg:block absolute left-full ml-8 top-0 w-full h-full bg-no-repeat border-2 border-brand-border-light dark:border-gray-700 rounded-lg shadow-2xl pointer-events-none transition-opacity duration-300 z-10 ${isZooming ? 'opacity-100' : 'opacity-0'}`}
            style={{
                backgroundImage: `url(${selectedImage})`,
                backgroundPosition: bgPosition,
                backgroundSize: '200%',
            }}
          />
        </div>

        <div>
          <div className="flex justify-between items-center w-full gap-4 mb-6 text-brand-naval dark:text-white">
              <h1 className="text-3xl md:text-4xl font-display uppercase leading-tight flex-1 text-left">
                  {product.name}
              </h1>
              <div className="flex-shrink-0 flex flex-col items-end min-w-[120px]">
                  <StarRating rating={product.rating} totalReviews={allReviews.length} />
              </div>
          </div>

          <p className="text-lg text-brand-naval/60 dark:text-gray-400 mt-2">{product.desc}</p>
          <p className="text-3xl font-bold mt-4 text-brand-naval dark:text-white">R$ {product.price.toFixed(2)}</p>

          <div className="mt-6">
            <h3 className="text-sm font-semibold uppercase tracking-wider text-brand-naval/70 dark:text-gray-300">Selecione a Cor</h3>
            <div className="flex items-center gap-3 mt-2">
              {product.colors.map(color => (
                <button 
                  key={color}
                  onClick={() => setSelectedColor(color)}
                  className={`px-4 py-2 rounded-full text-sm font-medium border-2 transition-colors ${selectedColor === color ? 'bg-brand-naval text-brand-off-white dark:bg-white dark:text-black border-transparent' : 'bg-transparent border-brand-border-light text-brand-naval/60 dark:border-gray-600 dark:text-gray-400'}`}
                >
                  {color}
                </button>
              ))}
            </div>
          </div>

          <div className="mt-6">
            <h3 className="text-sm font-semibold uppercase tracking-wider text-brand-naval/70 dark:text-gray-300">Selecione o Tamanho</h3>
            <div className="flex flex-wrap items-center gap-3 mt-2">
              {product.sizes.map(size => (
                <button 
                  key={size}
                  onClick={() => setSelectedSize(size)}
                  className={`px-4 py-2 rounded-full text-sm font-medium border-2 transition-colors ${selectedSize === size ? 'bg-brand-naval text-brand-off-white dark:bg-white dark:text-black border-transparent' : 'bg-transparent border-brand-border-light text-brand-naval/60 dark:border-gray-600 dark:text-gray-400'}`}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          <div className="mt-8 flex items-center gap-4">
             {!isOutOfStock && (
                <div className="flex items-center gap-2 bg-brand-surface-light dark:bg-gray-800 rounded-full p-1 border border-brand-border-light dark:border-white/10">
                <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="p-2.5 rounded-full hover:bg-brand-off-white dark:hover:bg-gray-700 text-brand-naval dark:text-white"><MinusIcon className="w-5 h-5" /></button>
                <span className="px-4 font-semibold text-lg text-brand-naval dark:text-white">{quantity}</span>
                <button onClick={() => setQuantity(q => Math.min(product.stock, q + 1))} className="p-2.5 rounded-full hover:bg-brand-off-white dark:hover:bg-gray-700 text-brand-naval dark:text-white"><PlusIcon className="w-5 h-5" /></button>
                </div>
             )}
            <button 
              onClick={handleAddToCartClick}
              disabled={isOutOfStock}
              className="flex-1 bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-semibold py-4 rounded-full hover:scale-105 transition-all shadow-lg disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {isOutOfStock ? 'Esgotado' : 'Adicionar ao Carrinho'}
            </button>
            <button 
                onClick={() => onToggleWishlist(product)}
                className="p-4 bg-brand-surface-light dark:bg-gray-800 rounded-full hover:bg-brand-off-white dark:hover:bg-gray-700 transition-colors border border-brand-border-light dark:border-white/10"
                aria-label="Adicionar aos Favoritos"
            >
              {isWishlisted ? <HeartIconSolid className="w-6 h-6 text-red-500" /> : <HeartIcon className="w-6 h-6 text-brand-naval dark:text-white" />}
            </button>
          </div>

          <div className="mt-8 pt-6 border-t border-brand-border-light dark:border-gray-700">
            <h3 className="font-bold text-xl text-brand-naval dark:text-white">Descrição</h3>
            <p className="mt-2 text-brand-naval/70 dark:text-gray-300 leading-relaxed">{product.longDescription}</p>
          </div>
        </div>
      </div>
       <div className="mt-16 pt-8 border-t border-brand-border-light dark:border-gray-700">
            <h2 className="text-3xl font-bold mb-8 text-brand-naval dark:text-white">Avaliações de Clientes</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div>
                    <h3 className="text-2xl font-bold mb-6 text-brand-naval dark:text-white">Deixe sua avaliação</h3>
                    <ReviewForm onSubmit={handleReviewSubmit} />
                </div>
                <div className="space-y-6">
                    {allReviews.length > 0 ? (
                        allReviews.map((review, index) => (
                            <div key={index} className="bg-brand-surface-light dark:bg-brand-naval-light/5 p-6 rounded-xl border border-brand-border-light dark:border-white/5">
                                <div className="flex items-center justify-between mb-2">
                                    <p className="font-bold text-xl text-brand-naval dark:text-white">{review.author}</p>
                                    <div className="flex">
                                        {[...Array(5)].map((_, i) => (
                                            <StarIcon key={i} className={`w-5 h-5 ${i < review.rating ? 'text-brand-yellow' : 'text-brand-naval/20 dark:text-gray-600'}`} />
                                        ))}
                                    </div>
                                </div>
                                <p className="text-lg text-brand-naval/70 dark:text-gray-300 leading-relaxed">{review.comment}</p>
                            </div>
                        ))
                    ) : (
                        <p className="text-lg text-brand-naval/40 dark:text-gray-500 italic">Este produto ainda não tem avaliações. Seja o primeiro a avaliar!</p>
                    )}
                </div>
            </div>
        </div>
        {relatedProducts.length > 0 && (
            <div className="mt-20 pt-10 border-t border-brand-border-light dark:border-gray-700">
                <h2 className="text-3xl font-bold mb-8 text-center uppercase font-display text-brand-naval dark:text-white">Você Também Pode Gostar</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-8">
                    {relatedProducts.map(relatedProduct => (
                        <div
                            key={relatedProduct.id}
                            className="group overflow-hidden rounded-lg cursor-pointer bg-brand-surface-light/40 dark:bg-brand-naval-light/5 flex flex-col relative border border-brand-border-light dark:border-white/5 hover:bg-brand-surface-light transition-all"
                            onClick={() => onNavigate('productDetail', relatedProduct)}
                        >
                            {relatedProduct.stock === 0 && (
                                <div className="absolute top-3 left-3 bg-red-500 text-white text-xs font-bold uppercase px-2 py-1 rounded-full z-10">
                                    Esgotado
                                </div>
                            )}
                            <div className="overflow-hidden bg-brand-surface-light">
                                <img src={relatedProduct.image} alt={relatedProduct.name} className="w-full h-80 object-cover transition-transform duration-500 group-hover:scale-105" onContextMenu={(e) => e.preventDefault()} />
                            </div>
                            <div className="p-4 flex flex-col flex-grow">
                                <h3 className="font-bold text-lg truncate text-brand-naval dark:text-white">{relatedProduct.name}</h3>
                                <p className="text-sm text-brand-naval/50 dark:text-gray-400">{relatedProduct.brand}</p>
                                <p className="mt-2 font-semibold text-lg mt-auto text-brand-naval dark:text-white">R$ {relatedProduct.price.toFixed(2)}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};

export default ProductDetail;

