  onNavigate: (page: string, product?: Product, filters?: Partial<Filters>) => void;
}

const categories = [
  { name: 'Basquete', image: 'https://images.pexels.com/photos/163452/basketball-dunk-blue-game-163452.jpeg?auto=compress&cs=tinysrgb&w=800' },
  { name: 'Corrida', image: 'https://images.pexels.com/photos/3763879/pexels-photo-3763879.jpeg?auto=compress&cs=tinysrgb&w=800' },
  { name: 'Lifestyle', image: 'https://images.pexels.com/photos/1191531/pexels-photo-1191531.jpeg?auto=compress&cs=tinysrgb&w=800' },
];

const FeaturedCategories: React.FC<FeaturedCategoriesProps> = ({ onNavigate }) => {
  const handleShopCategory = (categoryName: string) => {
    if (categoryName === 'Basquete' || categoryName === 'Corrida') {
      onNavigate('shop', undefined, { style: [categoryName] });
    } else if (categoryName === 'Lifestyle') {
      onNavigate('shop', undefined, { brand: ['Nike'] });
    } else {
      onNavigate('shop');
    }
  };

  return (
    <section className="pb-16 md:pb-24 bg-gray-300 dark:bg-[#181818]">
      <div className="container mx-auto px-4 grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8">
        {categories.map((category) => (
          <div key={category.name} className="relative group overflow-hidden rounded-xl aspect-[3/4]">
            <img 
              src={category.image} 
              alt={category.name} 
              className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
              onContextMenu={(e) => e.preventDefault()} 
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent flex flex-col justify-end p-8">
              <h4 className="text-white text-2xl font-black uppercase italic mb-4 tracking-tighter">{category.name}</h4>
              <button 
                onClick={() => handleShopCategory(category.name)}
                className="w-full bg-white text-black font-bold py-3 rounded-full hover:bg-brand-yellow transition-all duration-300 hover:scale-105"
              >
                Explorar {category.name}
              </button>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default FeaturedCategories;

import React, { useState, useRef } from 'react';
import { PlayCircleIcon, PauseIcon, VolumeUpIcon, VolumeOffIcon } from './Icons';

export default function Hero() {
  const [isPlaying, setIsPlaying] = useState(true);
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLVideoElement>(null);

  const toggleVideo = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
      } else {
        videoRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
      setIsMuted(!isMuted);
    }
  };

  return (
    <div className="relative h-[85vh] w-full bg-black overflow-hidden">
      <video 
        ref={videoRef}
        autoPlay 
        muted 
        loop 
        playsInline
        className="absolute inset-0 w-full h-full object-cover opacity-90"
      >
        <source src="https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4" type="video/mp4" />
      </video>
      <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-transparent to-black/30" />

      {/* Video Controls Group */}
      <div className="absolute bottom-8 right-8 z-30 flex items-center gap-4">
        {/* Mute/Unmute Button */}
        <button 
          onClick={toggleMute}
          className="w-12 h-12 flex items-center justify-center bg-black/50 rounded-full text-white hover:text-brand-yellow hover:bg-black/70 transition-all backdrop-blur-md border border-white/20 shadow-xl"
          aria-label={isMuted ? "Ativar som" : "Desativar som"}
        >
          {isMuted ? (
            <VolumeOffIcon className="w-6 h-6" />
          ) : (
            <VolumeUpIcon className="w-6 h-6" />
          )}
        </button>

        {/* Pause/Play Toggle Button */}
        <button 
          onClick={toggleVideo}
          className="w-12 h-12 flex items-center justify-center bg-black/50 rounded-full text-white hover:text-brand-yellow hover:bg-black/70 transition-all backdrop-blur-md border border-white/20 shadow-xl"
          aria-label={isPlaying ? "Pausar vídeo" : "Tocar vídeo"}
        >
          {isPlaying ? (
            <PauseIcon className="w-6 h-6" />
          ) : (
            <PlayCircleIcon className="w-6 h-6" />
          )}
        </button>
      </div>
    </div>
  );
}

