import React, { useState, useMemo } from 'react';
import { Product, Filters } from '../data/products';
import { HeartIcon, HeartIconSolid, StarIcon } from './Icons';

interface ShopProps {
  products: Product[];
  onNavigate: (page: string, product: Product) => void;
  wishlistItems: Product[];
  onToggleWishlist: (product: Product) => void;
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

const normalizeText = (text: string) => {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
};

const StarRatingDisplay: React.FC<{ rating: number; reviewCount: number }> = ({ rating, reviewCount }) => (
    <div className="flex flex-col items-end justify-start gap-1">
        <div className="flex items-center justify-end">
            {[...Array(5)].map((_, i) => (
                <StarIcon key={i} className={`w-3.5 h-3.5 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-brand-naval/30 dark:text-gray-600'}`} />
            ))}
        </div>
        <span className="text-xs text-brand-naval/60 dark:text-gray-400 font-medium text-right leading-none whitespace-nowrap">
            ({reviewCount > 0 ? reviewCount : Math.floor(Math.random() * 20) + 1} avaliações)
        </span>
    </div>
