    if (sortOrder === 'price-desc') return list.sort((a, b) => b.price - a.price);
    return list;
  }, [filteredProducts, sortOrder]);

  const toggleFilter = (key: keyof Filters, value: string) => {
    const current = filters[key];
    if (Array.isArray(current)) {
      const next = current.includes(value) 
        ? current.filter(v => v !== value) 
        : [...current, value];
      onFiltersChange({ ...filters, [key]: next });
    } else {
      onFiltersChange({ ...filters, [key]: value });
    }
  };

  const brands = Array.from(new Set(products.map(p => p.brand)));

  return (
    <div className="w-full bg-brand-off-white dark:bg-brand-naval-dark transition-colors duration-300">
      <div className="container mx-auto px-4 py-12">
        <div className="flex flex-col lg:flex-row gap-12">
          {/* Sidebar Filters */}
          <aside className="w-full lg:w-1/4">
            <div className="sticky top-28 bg-brand-surface-light dark:bg-brand-naval-light/20 p-8 rounded-2xl border border-brand-border-light dark:border-white/5 backdrop-blur-md shadow-lg">
              <h2 className="text-2xl font-bold uppercase mb-8 font-display tracking-tight text-brand-naval dark:text-brand-off-white">Filtros</h2>

              <div className="space-y-10">
                <div className="bg-brand-yellow/10 p-4 rounded-xl border border-brand-yellow/30">
                   <label className="flex items-center justify-between cursor-pointer">
                      <span className="font-black text-xs uppercase text-brand-naval dark:text-brand-yellow italic tracking-widest">Apenas Ofertas</span>
                      <input 
                        type="checkbox" 
                        checked={filters.onSale} 
                        onChange={() => onFiltersChange({...filters, onSale: !filters.onSale})}
                        className="w-5 h-5 rounded border-brand-yellow bg-transparent text-brand-yellow focus:ring-brand-yellow"
                      />
                   </label>
                </div>

                <div>
                  <h3 className="font-bold text-base uppercase mb-4 tracking-widest text-brand-naval/70 dark:text-brand-yellow">Categoria</h3>
                  <div className="space-y-3">
                    {["Todos", "Tênis", "Moda Praia", "Life Style", "Artigos Esportivos", "Suplementos"].map(cat => (
                      <button 
                        key={cat} 
                        onClick={() => onFiltersChange({ ...filters, category: cat })}
                        className={`block text-base transition-colors ${filters.category === cat ? 'text-brand-naval dark:text-brand-yellow font-black' : 'text-brand-naval/50 hover:text-brand-naval dark:text-gray-400 dark:hover:text-white'}`}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <h3 className="font-bold text-base uppercase mb-4 tracking-widest text-brand-naval/70 dark:text-brand-yellow">Marca</h3>
                  <div className="space-y-3">
                    {brands.map(brand => (
                      <label key={brand} className="flex items-center gap-3 cursor-pointer group">
                        <input 
                          type="checkbox" 
                          checked={filters.brand.includes(brand)}
                          onChange={() => toggleFilter('brand', brand)}
                          className="w-5 h-5 rounded border-brand-border-light dark:border-white/10 bg-transparent text-brand-naval dark:text-brand-yellow focus:ring-brand-yellow" 
                        />
                        <span className="text-base font-medium text-brand-naval/60 group-hover:text-brand-naval dark:text-gray-400 dark:group-hover:text-white transition-colors">{brand}</span>
                      </label>
                    ))}
                  </div>
                </div>

                <button 
                  onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:'', onSale: false})}
                  className="w-full bg-brand-naval dark:bg-brand-yellow text-brand-off-white dark:text-black font-black py-4 rounded-full text-sm uppercase hover:scale-105 transition-all shadow-md"
                >
                  Limpar Filtros
                </button>
              </div>
            </div>
          </aside>

          {/* Product Grid */}
          <main className="w-full lg:w-3/4">
            <div className="flex justify-between items-center mb-10 bg-brand-surface-light dark:bg-brand-naval-light/10 p-6 rounded-xl border border-brand-border-light dark:border-white/5 backdrop-blur-md shadow-sm">
               <div className="flex flex-col">
                  <p className="text-base font-bold text-brand-naval dark:text-brand-off-white">{sortedProducts.length} Produtos Encontrados</p>
                  {filters.category !== 'Todos' && <span className="text-[10px] uppercase font-black text-brand-yellow">
                    {Array.isArray(filters.category) ? "Filtro Combinado" : filters.category}
                  </span>}
               </div>
               <div className="flex items-center gap-3">
                 <span className="text-[10px] uppercase font-black text-brand-naval/40 dark:text-gray-400 tracking-widest">Ordenar por:</span>
                 <select 
                   value={sortOrder} 
                   onChange={(e) => setSortOrder(e.target.value)} 
                   className="bg-transparent font-bold text-sm focus:outline-none cursor-pointer border-none ring-0 text-brand-naval dark:text-brand-off-white"
                 >
                    <option value="featured">Destaques</option>
                    <option value="price-asc">Menor Preço</option>
                    <option value="price-desc">Maior Preço</option>
                 </select>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {sortedProducts.length > 0 ? sortedProducts.map(product => {
                  const isWish = wishlistItems.some(i => i.id === product.id);
                  const isOutOfStock = product.stock === 0;
                  return (
                      <div 
                        key={product.id} 
                        className="group bg-brand-surface-light/40 dark:bg-brand-naval-light/5 rounded-2xl border border-brand-border-light dark:border-white/5 overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-500 flex flex-col h-full hover:bg-brand-surface-light"
                        onClick={() => onNavigate('productDetail', product)}
                      >
                          <div className="relative aspect-[4/5] overflow-hidden bg-brand-surface-light dark:bg-black/20">
                              {isOutOfStock && (
                                <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10">
                                  <span className="text-white font-bold uppercase tracking-widest border-2 border-white px-6 py-2">Esgotado</span>
                                </div>
                              )}
                              {product.onSale && !isOutOfStock && (
                                <div className="absolute top-4 left-4 bg-brand-yellow text-black font-black text-[10px] uppercase px-3 py-1 rounded-full z-20 shadow-md">
                                    Oferta
                                </div>
                              )}
                              <img 
                                src={product.image} 
                                className={`w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ${isOutOfStock ? 'grayscale opacity-80' : ''}`} 
                                alt={product.name} 
                              />
                              <button 
                                  onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }} 
                                  className="absolute top-4 right-4 p-3 bg-brand-off-white/80 dark:bg-black/40 rounded-full backdrop-blur-md shadow-lg z-20 hover:scale-110 transition-transform text-brand-naval dark:text-brand-off-white"
                              >
                                  {isWish ? <HeartIconSolid className="w-6 h-6 text-red-500" /> : <HeartIcon className="w-6 h-6" />}
                              </button>
                          </div>
                          <div className="p-6 flex flex-col flex-1">
                              <div className="flex justify-between items-start mb-4">
                                  <h3 className="font-black text-[10px] uppercase truncate pr-3 group-hover:text-brand-naval dark:group-hover:text-brand-yellow transition-colors tracking-tight text-brand-naval dark:text-white">{product.name}</h3>
                                  <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                              </div>
                              <p className="text-[10px] text-brand-naval/50 dark:text-gray-400 font-bold mb-6 tracking-widest uppercase">{product.brand} | {product.style}</p>
                              <div className="mt-auto pt-6 border-t border-brand-border-light dark:border-white/5 flex justify-between items-center">
                                <p className="font-black text-2xl text-brand-naval dark:text-white">R$ {product.price.toFixed(2)}</p>
                                <span className="text-[10px] font-black uppercase tracking-widest text-brand-naval dark:text-brand-yellow">Ver Detalhes</span>
                              </div>
                          </div>
                      </div>
                  );
              }) : (
                <div className="col-span-full py-20 text-center">
                    <p className="text-xl font-bold text-brand-naval/50 dark:text-gray-400 italic">Nenhum produto encontrado com os filtros atuais.</p>
                    <button 
                      onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:'', onSale: false})}
                      className="mt-6 text-brand-yellow underline font-bold uppercase tracking-widest text-xs"
                    >
                      Remover todos os filtros
                    </button>
                </div>
              )}
            </div>
          </main>
        </div>
      </div>
    </div>
  );
}

