        <div className="mt-8 md:mt-12 relative">
          <div 
            ref={scrollContainerRef}
            className="flex items-start space-x-4 md:space-x-8 overflow-x-auto pb-4 -mx-4 px-4 scrollbar-hide"
          >
            {spotlightItems.map((item) => (
