            {[...Array(5)].map((_, i) => (
                <StarIcon key={i} className={`w-3.5 h-3.5 ${i < Math.round(rating) ? 'text-brand-yellow' : 'text-brand-naval/30 dark:text-gray-600'}`} />
            ))}
        </div>
        <span className="text-xs text-brand-naval/60 dark:text-gray-400 font-medium text-right leading-none whitespace-nowrap">
            ({reviewCount > 0 ? reviewCount : Math.floor(Math.random() * 20) + 1} avaliações)
        </span>
    </div>
);

export default function Shop({ products, onNavigate, wishlistItems, onToggleWishlist, filters, onFiltersChange }: ShopProps) {
  const [sortOrder, setSortOrder] = useState('featured');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
        let catMatch = false;
        if (Array.isArray(filters.category)) {
            catMatch = filters.category.length === 0 || filters.category.includes(p.category);
        } else {
            catMatch = filters.category === 'Todos' || p.category === filters.category;
        }

        const brandMatch = filters.brand.length === 0 || filters.brand.includes(p.brand);
        const genderMatch = filters.gender.length === 0 || filters.gender.includes(p.gender);
        const styleMatch = filters.style.length === 0 || filters.style.includes(p.style);
        const saleMatch = !filters.onSale || p.onSale === true;

        let queryMatch = true;
        if (filters.query) {
            const normalizedQuery = normalizeText(filters.query);
            queryMatch = normalizeText(p.name).includes(normalizedQuery) || 
                         normalizeText(p.brand).includes(normalizedQuery);
        }
        return catMatch && brandMatch && genderMatch && styleMatch && queryMatch && saleMatch;
    });
  }, [products, filters]);

  const sortedProducts = useMemo(() => {
    const list = [...filteredProducts];
    if (sortOrder === 'price-asc') return list.sort((a, b) => a.price - b.price);
    if (sortOrder === 'price-desc') return list.sort((a, b) => b.price - a.price);
    return list;
  }, [filteredProducts, sortOrder]);

  const toggleFilter = (key: keyof Filters, value: string) => {
    const current = filters[key];
    if (Array.isArray(current)) {
      const next = current.includes(value) 
        ? current.filter(v => v !== value) 
        : [...current, value];
      onFiltersChange({ ...filters, [key]: next });
    } else {
      onFiltersChange({ ...filters, [key]: value });
    }
  };

  const brands = Array.from(new Set(products.map(p => p.brand))).sort();

  return (
    <div className="w-full bg-brand-off-white dark:bg-brand-naval-dark transition-colors duration-300">
      <div className="container mx-auto px-4 py-12">
        <div className="flex flex-col lg:flex-row gap-12">
          {/* Sidebar Filters */}
          <aside className="w-full lg:w-1/4">
            <div className="sticky top-28 bg-white dark:bg-brand-naval-light/10 p-8 rounded-3xl border border-brand-border-light dark:border-white/5 shadow-2xl backdrop-blur-xl">
              <div className="mb-10 flex justify-between items-center">
                  <h2 className="text-3xl font-black uppercase font-display tracking-tighter text-brand-naval dark:text-brand-off-white">Filtros</h2>
                  <span className="text-[10px] font-black bg-brand-yellow text-black px-2 py-1 rounded">PRO</span>
              </div>

              <div className="space-y-12">
                <div>
                  <h3 className="font-bold text-xs uppercase mb-6 tracking-[0.2em] text-brand-naval/40 dark:text-brand-yellow/60">Categorias</h3>
                  <div className="space-y-4">
                    {["Todos", "Tênis", "Moda Praia", "Life Style", "Artigos Esportivos", "Suplementos", "Fisio e Ortopédicos"].map(cat => (
                      <button 
                        key={cat} 
                        onClick={() => onFiltersChange({ ...filters, category: cat })}
                        className={`block text-base transition-all text-left w-full hover:translate-x-1 ${filters.category === cat ? 'text-brand-naval dark:text-white font-black border-l-4 border-brand-yellow pl-3' : 'text-brand-naval/40 hover:text-brand-naval dark:text-gray-500 dark:hover:text-white'}`}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <h3 className="font-bold text-xs uppercase mb-6 tracking-[0.2em] text-brand-naval/40 dark:text-brand-yellow/60">Gênero</h3>
                  <div className="space-y-4">
                    {["Masculino", "Feminino", "Kids"].map(gender => (
                      <label key={gender} className="flex items-center gap-4 cursor-pointer group">
                        <div className="relative flex items-center">
                            <input 
                              type="checkbox" 
                              checked={filters.gender.includes(gender)}
                              onChange={() => toggleFilter('gender', gender)}
                              className="peer w-6 h-6 rounded-md border-2 border-brand-border-light dark:border-white/10 bg-transparent text-brand-yellow focus:ring-brand-yellow transition-all" 
                            />
                            <div className="absolute inset-0 m-auto w-3 h-3 bg-brand-yellow rounded-sm scale-0 peer-checked:scale-100 transition-transform"></div>
                        </div>
                        <span className="text-base font-bold text-brand-naval/50 group-hover:text-brand-naval dark:text-gray-500 dark:group-hover:text-white transition-colors uppercase tracking-tight">{gender}</span>
                      </label>
                    ))}
                  </div>
                </div>

                {/* BOTÃO DE OFERTAS MODERNO - ALINHADO E ESTILIZADO */}
                <div className="pt-10 border-t border-brand-border-light dark:border-white/10">
                    <button 
                        onClick={() => onFiltersChange({...filters, onSale: !filters.onSale})}
                        className={`w-full py-5 rounded-2xl text-[11px] font-black uppercase tracking-[0.3em] transition-all relative overflow-hidden group shadow-xl ${filters.onSale ? 'bg-brand-yellow text-black' : 'bg-black dark:bg-white text-white dark:text-black hover:scale-[1.02]'}`}
                    >
                        <span className="relative z-10">{filters.onSale ? 'Sair das Ofertas' : 'Ofertas Imperdíveis'}</span>
                        {!filters.onSale && (
                            <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
                        )}
                    </button>

                    <button 
                        onClick={() => onFiltersChange({category:'Todos', brand:[], gender:[], style:[], query:'', onSale: false})}
                        className="w-full text-center mt-6 text-[10px] font-bold uppercase tracking-[0.2em] text-brand-naval/30 dark:text-gray-600 hover:text-brand-yellow transition-colors"
                    >
                        Resetar Filtros
                    </button>
                </div>
              </div>
            </div>
          </aside>

          {/* Product Grid */}
          <main className="w-full lg:w-3/4">
            <div className="flex justify-between items-center mb-10 bg-white dark:bg-brand-naval-light/5 p-8 rounded-3xl border border-brand-border-light dark:border-white/5 shadow-sm">
               <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-widest text-brand-yellow mb-1">Catálogo Recreio</span>
                  <p className="text-xl font-black text-brand-naval dark:text-brand-off-white">{sortedProducts.length} Itens Disponíveis</p>
               </div>
               <div className="flex items-center gap-4">
                 <span className="text-[10px] uppercase font-black text-brand-naval/30 dark:text-gray-500 tracking-[0.2em]">Sort:</span>
                 <select 
                   value={sortOrder} 
                   onChange={(e) => setSortOrder(e.target.value)} 
                   className="bg-transparent font-black text-xs uppercase tracking-widest focus:outline-none cursor-pointer border-none ring-0 text-brand-naval dark:text-brand-off-white"
                 >
                    <option value="featured">Padrão</option>
                    <option value="price-asc">Preço: Baixo</option>
                    <option value="price-desc">Preço: Alto</option>
                 </select>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
              {sortedProducts.length > 0 ? sortedProducts.map(product => {
                  const isWish = wishlistItems.some(i => i.id === product.id);
                  const isOutOfStock = product.stock === 0;
                  return (
                      <div 
                        key={product.id} 
                        className="group bg-white dark:bg-brand-naval-light/5 rounded-[2.5rem] overflow-hidden cursor-pointer shadow-lg hover:shadow-2xl transition-all duration-700 flex flex-col h-full border border-brand-border-light dark:border-white/5"
                        onClick={() => onNavigate('productDetail', product)}
                      >
                          <div className="relative aspect-[4/5] overflow-hidden bg-brand-surface-light dark:bg-black/40">
                              {isOutOfStock && (
                                <div className="absolute inset-0 bg-black/80 flex items-center justify-center z-20 backdrop-blur-sm">
                                  <span className="text-white font-black uppercase tracking-[0.3em] border-2 border-white px-8 py-3 text-xs">Esgotado</span>
                                </div>
                              )}
                              {product.onSale && !isOutOfStock && (
                                <div className="absolute top-6 left-6 bg-brand-yellow text-black font-black text-[10px] uppercase px-4 py-2 rounded-full z-20 shadow-2xl tracking-widest">
                                    Flash Sale
                                </div>
                              )}
                              <img 
                                src={product.image} 
                                className={`w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000 ${isOutOfStock ? 'grayscale opacity-50' : ''}`} 
                                alt={product.name} 
                              />
                              <button 
                                  onClick={(e) => { e.stopPropagation(); onToggleWishlist(product); }} 
                                  className="absolute top-6 right-6 p-4 bg-white/90 dark:bg-black/60 rounded-full backdrop-blur-xl shadow-2xl z-20 hover:scale-110 transition-all text-brand-naval dark:text-brand-off-white"
                              >
                                  {isWish ? <HeartIconSolid className="w-5 h-5 text-red-500" /> : <HeartIcon className="w-5 h-5" />}
                              </button>
                          </div>
                          <div className="p-8 flex flex-col flex-1">
                              <div className="flex justify-between items-start mb-6">
                                  <div className="flex-1 min-w-0 pr-4">
                                      <h3 className="font-black text-xs uppercase tracking-tight truncate text-brand-naval dark:text-white group-hover:text-brand-yellow transition-colors">{product.name}</h3>
                                      <p className="text-[10px] text-brand-naval/30 dark:text-gray-500 font-bold tracking-[0.2em] uppercase mt-1">{product.brand}</p>
                                  </div>
                                  <StarRatingDisplay rating={product.rating} reviewCount={product.reviews.length} />
                              </div>
                              <div className="mt-auto pt-8 border-t border-brand-border-light dark:border-white/5 flex justify-between items-center">
                                <p className="font-black text-xl text-brand-naval dark:text-white tracking-tighter">R$ {product.price.toFixed(2)}</p>
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-brand-yellow opacity-0 group-hover:opacity-100 transition-opacity">Ver Mais</span>
                              </div>
                          </div>
                      </div>
                  );
              }) : (
                <div className="col-span-full py-32 text-center">
                    <div className="inline-block p-10 bg-gray-200 dark:bg-brand-naval-light/10 rounded-full mb-8">
                        <StarIcon className="w-16 h-16 text-gray-400" />
                    </div>
                    <p className="text-2xl font-black text-brand-naval/30 dark:text-gray-600 uppercase tracking-tighter">Nenhum resultado encontrado</p>
                </div>
              )}
            </div>
          </main>
        </div>
      </div>
    </div>
  );
}

