                      <button 
                        key={cat} 
                        onClick={() => onFiltersChange({ ...filters, category: cat })}
                        className={`block text-base transition-all text-left w-full hover:translate-x-1 ${filters.category === cat ? 'text-brand-naval dark:text-white font-bold' : 'text-brand-naval/60 dark:text-gray-400'}`}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Gênero */}
                <div>
                  <h3 className="text-xs font-bold uppercase mb-4 tracking-widest text-brand-naval/40 dark:text-gray-500">Gênero</h3>
                  <div className="space-y-3">
                    {["Masculino", "Feminino", "Kids"].map(gender => (
                      <label key={gender} className="flex items-center gap-3 cursor-pointer group">
                        <input 
                          type="checkbox" 
                          checked={filters.gender.includes(gender)}
                          onChange={() => toggleFilter('gender', gender)}
                          className="w-5 h-5 rounded border-gray-300 dark:border-gray-700 bg-transparent text-brand-naval focus:ring-brand-naval" 
                        />
                        <span className="text-base font-medium text-brand-naval/60 group-hover:text-brand-naval dark:text-gray-400 dark:group-hover:text-white transition-colors">{gender}</span>
                      </label>
                    ))}
                  </div>
                </div>

                {/* Marcas */}
                <div>
                  <h3 className="text-xs font-bold uppercase mb-4 tracking-widest text-brand-naval/40 dark:text-gray-500">Marcas</h3>
                  <div className="space-y-3">
                    {brands.map(brand => (
                      <label key={brand} className="flex items-center gap-3 cursor-pointer group">
                        <input 
                          type="checkbox" 
                          checked={filters.brand.includes(brand)}
                          onChange={() => toggleFilter('brand', brand)}
                          className="w-5 h-5 rounded border-gray-300 dark:border-gray-700 bg-transparent text-brand-naval focus:ring-brand-naval" 
                        />
                        <span className="text-base font-medium text-brand-naval/60 group-hover:text-brand-naval dark:text-gray-400 dark:group-hover:text-white transition-colors">{brand}</span>
                      </label>
                    ))}
                  </div>
                </div>

