          <main className="w-full lg:w-3/4">
            <div className="flex justify-between items-center mb-10 bg-white dark:bg-brand-naval-light/5 p-6 rounded-2xl border border-brand-border-light dark:border-white/5">
               <div>
                  <p className="text-sm font-bold text-brand-naval dark:text-brand-off-white">{sortedProducts.length} Produtos Encontrados</p>
