                      <button 
                        key={cat} 
                        onClick={() => onFiltersChange({ ...filters, category: cat })}
                        className={`block text-base transition-all text-left w-full hover:text-brand-yellow ${filters.category === cat ? 'text-brand-yellow font-bold' : 'text-brand-naval/60 dark:text-gray-400'}`}
